-- Sections ---------------------------------------------------------------------
-- guide-band-4-to-5-roadmap: 24 sections
insert into public.toefl_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, p.id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (values
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:1')::uuid, 'rich_text', 'Who this roadmap is for', 1, '{"markdown":"This roadmap is for learners whose recent TOEFL iBT result, or whose full mock in the [Schood TOEFL simulator](https://toefl.schood.online/full-exam), sits at **band 4 or 4.5 overall** and who need **band 5 or higher**. On the 2026 scale that is the step from CEFR **B2** to CEFR **C1**, which ETS maps to the same number in every section and in the overall score.\n\nIt assumes you have already read the public modules [TOEFL Essentials](/toefl-essentials) and [Score Scale 2026](/score-scale-2026). Those explain the format. This guide is about the harder question: **which specific weaknesses keep a B2 learner at 4 or 4.5, and what to do about each one, in what order, week by week.**\n\nThe method has four parts:\n\n1. **Diagnose by section** with a full timed mock, not with a feeling.\n2. **Compare your evidence to the ETS descriptors** for B2 and C1 so you know what \"better\" looks like.\n3. **Run weekly targets** that put most of your hours on the section with the best return.\n4. **Keep an error log** and use it every week to decide what to practise next.\n\nA realistic expectation: the B2 to C1 step is a genuine change in language ability, not a trick. Many learners need several months of steady work for it. This guide cannot promise a band, and nothing here is a score prediction. What it can do is stop you spending hours on things that do not move the descriptors."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:2')::uuid, 'checklist', 'What you will be able to do', 2, '{"items":["Read your section bands and work out exactly how the overall band was rounded","Name the descriptor difference between B2 and C1 in each of the four sections","Choose one priority section and one maintenance section for the next four weeks","Run a weekly cycle of drills, timed sets and review in the Schood simulator","Keep a structured error log and turn it into next week''s drills","Use checkpoints and decision rules instead of guessing when a plan is not working"]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:3')::uuid, 'rich_text', 'Band 4 and band 5 on the 2026 scale', 3, '{"markdown":"Since 21 January 2026, ETS reports each section and the overall score on a **1–6 scale in half-band steps**. The scale is aligned to the CEFR so that the same number means the same level everywhere: **4–4.5 is B2** and **5–5.5 is C1** in Reading, Listening, Writing, Speaking and overall.\n\nDuring a two-year transition, the score report also shows a comparable 0–120 total. ETS''s comparison table gives these minimums:\n\n| Band | CEFR | Comparable 0–120 total |\n|---|---|---|\n| 4 | B2 | 72+ |\n| 4.5 | B2 | 86+ |\n| 5 | C1 | 95+ |\n| 5.5 | C1 | 107+ |\n\nSection by section, the same table puts band 5 at roughly **24–26 for Reading, 22–25 for Listening, 24–26 for Writing and 25–26 for Speaking** on the old 0–30 scale, and band 4 at **18–21, 17–19, 17–20 and 20–22**. If your target school still publishes an old-style requirement such as \"95 total\", this is why it lines up with band 5.\n\n**Practical point:** ETS sets no pass mark. Each institution sets its own requirement and some also set section minimums. Before you plan, write your exact target down: overall band, any section minimums, and the deadline for your application."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:4')::uuid, 'rich_text', 'How the overall band is calculated', 4, '{"markdown":"The overall band is the **average of the four section bands, rounded to the nearest half band**. ETS gives two worked examples on its own pages: an average of **5.125 is reported as 5**, and an average of **5.25 is reported as 5.5**. So a quarter-band average rounds up, and anything below it rounds down.\n\nThat arithmetic matters when you are near the line:\n\n| Reading | Listening | Writing | Speaking | Average | Overall |\n|---|---|---|---|---|---|\n| 5 | 5 | 5 | 5 | 5.00 | 5 |\n| 5.5 | 5 | 4.5 | 4.5 | 4.875 | 5 |\n| 5 | 5 | 4.5 | 4.5 | 4.75 | 5 |\n| 5 | 4.5 | 4.5 | 4.5 | 4.625 | 4.5 |\n| 5.5 | 5.5 | 4 | 4 | 4.75 | 5 |\n\nThree lessons follow from the table:\n\n- **One section at 4.5 does not stop an overall 5**, as long as the others hold. Two sections at 4.5 are also survivable if the other two are at 5 or above.\n- **A strong section can carry a weak one**, but only if the institution has no section minimums. Check this before you rely on it.\n- **Every half band counts the same.** Moving Speaking from 4 to 4.5 changes the average exactly as much as moving Reading from 5 to 5.5. The cheapest half band is the one to chase first."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:5')::uuid, 'rich_text', 'Step 1: get a clean baseline', 5, '{"markdown":"Take one **full timed mock in the [Schood simulator](https://toefl.schood.online/full-exam)** in the real order: Reading, Listening, Writing, Speaking, with no pauses between sections, because the real test has no scheduled breaks. Use the same desk, the same time of day and the same note-taking material you will use on test day.\n\nThen record, in your error log (format later in this guide):\n\n- the band for each section\n- for Reading and Listening, which **task types** produced the misses\n- for Writing, the task score pattern: Build a Sentence accuracy, email and discussion feedback\n- for Speaking, Listen and Repeat accuracy and the interview feedback\n- how you felt about **time** in each section: rushed, comfortable, or with time left over\n\n**Do not average two old mocks with one new one.** Your baseline is the most recent full mock taken under real conditions. If you have not taken one in the last two weeks, take one now before you read further."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:6')::uuid, 'rich_text', 'Step 2: read your profile', 6, '{"markdown":"Most band 4–4.5 learners fall into one of four profiles. Find yours, because each one has a different first move.\n\n- **Profile A: receptive strong, productive weak.** Reading and Listening at 5 or above, Writing or Speaking at 4 or below. Your fastest gains are almost always in Writing and Speaking, where specific, learnable habits are scored.\n- **Profile B: productive strong, receptive weak.** Writing and Speaking at 4.5 or above, Reading or Listening at 4. Your ceiling is vocabulary range and inference speed. Gains come slower but last.\n- **Profile C: flat 4.** All four sections at 4 or 4.5. You need broad C1 input (more reading and listening at C1 difficulty) plus accuracy work in Writing. Choose one productive skill to push first.\n- **Profile D: one collapse.** Three sections at 4.5 or 5, one at 3.5 or below. Fix the collapse first; the averaging table shows why a single low section is the most expensive problem you have.\n\nWrite your profile at the top of your error log. You will check it again at every checkpoint."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:7')::uuid, 'rich_text', 'Reading: what separates B2 from C1', 7, '{"markdown":"ETS''s performance descriptors describe a **B2 reader** as someone who uses several strategies, such as finding main points and using context clues, adjusts reading speed to the text, and can tell when a text gives facts and when it argues. A **C1 reader** handles long, complex texts and picks up finer points of detail, including attitudes and opinions that are implied rather than stated. C1 readers use contextual, grammatical and lexical cues to infer attitude and anticipate what comes next.\n\nTranslated into the three 2026 Reading tasks:\n\n- **Complete the Words** rewards exactly those grammatical and lexical cues. At B2 you complete common words; at C1 you complete academic words whose form depends on grammar (*-tion* or *-tive*, *-ed* or *-ing*, singular or plural) without hesitating.\n- **Read in Daily Life** rewards the purpose of a message, informal and telegraphic language, and scanning. The blueprint spans A1 to C1 here; for many B2 learners the remaining misses are about implied meaning (\"what does the writer suggest…\").\n- **Read an Academic Passage** has questions on detail, vocabulary in context, inference, the relationship between ideas and the purpose of part of the text. The B2 ceiling is often the **purpose and relationship** questions, not detail.\n\nReading is two-stage adaptive: your performance in the first part decides the difficulty of the second part. ETS does not publish the routing rule, so treat the first stage as the part where careless errors cost the most."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:8')::uuid, 'rich_text', 'Reading: the moves that work at this level', 8, '{"markdown":"- **Daily Complete the Words sets.** Two or three paragraphs a day, timed, then a full review of every miss by error type. The [Complete the Words Drills](/guide-complete-the-words-drills) guide has twelve graded paragraphs and the review method.\n- **Purpose-and-relationship drill.** After every academic passage you practise, write one line per paragraph: \"This paragraph exists to…\". Then compare with the questions. C1 readers see structure; this drill trains it.\n- **Implied-meaning drill.** For each Daily Life text, write what the writer wants the reader to do or believe, in your own words, before you look at the options.\n- **Academic vocabulary in families.** Learn words with their family: *analyse, analysis, analytical, analytically*. Complete the Words punishes knowing only one form.\n- **Do not read slower to be safe.** If your mock showed time left over in Reading, you are probably fine on speed. If you rushed, the fix is fewer re-reads, not faster eyes: answer, mark doubts, move on."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:9')::uuid, 'rich_text', 'Listening: what separates B2 from C1', 9, '{"markdown":"ETS describes a **B2 listener** as able to follow extended speech and complex arguments when the topic is reasonably familiar and the argument is signposted, and to separate main themes from asides. A **C1 listener** uses contextual, grammatical and lexical cues to infer attitude, mood and intention, recognises a wide range of idioms, and follows most lectures and discussions with ease.\n\nIn the 2026 Listening section that difference shows up in four places:\n\n- **Listen and Choose a Response:** the question or statement is heard, not shown. B2 listeners miss replies that depend on tone or implied meaning (a polite refusal, a surprised question).\n- **Listen to a Conversation:** two questions per conversation, often about what a speaker implies or will do next.\n- **Listen to an Announcement:** short campus messages about schedules, rules or events; misses are usually the detail that changed or the action the listener must take.\n- **Listen to an Academic Talk:** about 100–250 words with four questions; C1 questions ask why the speaker mentions something and how the talk is organised.\n\nAudio is played once, and voices include North American, British and Australian English."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:10')::uuid, 'rich_text', 'Listening: the moves that work at this level', 10, '{"markdown":"- **Function-first listening.** For every talk, write two words while listening: the speaker''s purpose (\"compare\", \"warn\", \"define\") and the structure (\"cause → effect\"). Questions about why something is mentioned become easier when you were tracking purpose all along.\n- **Reply-type drill for Choose a Response.** After each item, label the correct reply: agreeing, declining, correcting, clarifying, reassuring. Patterns appear quickly, and patterns are what you need when the audio is gone.\n- **Accent rotation.** Spend each listening session on one variety (North American, British or Australian) and rotate. B2 listeners often have one comfortable accent.\n- **Post-listening transcript check.** When practice material has a transcript, read it only after answering, and underline the exact words that carried the answer. Misses usually cluster around signal phrases (\"which is why\", \"that said\", \"not to mention\").\n- **Prediction habit.** Before each conversation''s questions appear, say to yourself what the speakers will probably do next. ETS lists prediction as a tested skill."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:11')::uuid, 'rich_text', 'Writing: what separates 4 from 5', 11, '{"markdown":"Writing has three tasks: **Build a Sentence** (10 items, 1 point each), **Write an Email** (7 minutes, scored 0–5) and **Write for an Academic Discussion** (10 minutes, scored 0–5). The blueprint gives Writing 20 raw points, so Build a Sentence carries half of them. ETS does not publish how raw points convert to bands, so treat every point as worth fighting for.\n\nThe ETS scoring guides draw a clear line between a **4** (\"generally successful\") and a **5** (\"fully successful\") on both written tasks:\n\n- a 4 has adequate elaboration, some syntactic variety, appropriate word choice and few errors\n- a 5 has elaboration that effectively supports the purpose, effective variety, precise and idiomatic word choice, and almost no errors beyond typical timed-writing slips\n\nETS''s own email sample shows how thin that line is: a response that did everything asked was held at 4 mainly because of a consequential verb-form error. At this level, **accuracy and precision move scores more than length.**"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:12')::uuid, 'rich_text', 'Writing: the moves that work at this level', 12, '{"markdown":"- **Build a Sentence to 10 out of 10.** These are machine-scored and reward grammar you can drill: question word order, relative clauses, embedded questions, passive forms. Track every miss by structure in your log.\n- **One precise verb per sentence.** Replace *get, make, do, have* with the verb that names the action: *obtain, arrange, submit, postpone*. This is the cheapest route to \"precise, idiomatic word choice\".\n- **Social conventions in the email.** Score 5 emails handle requests, apologies and refusals with the right politeness for the reader. Practise the same request written to a professor, an office and a classmate.\n- **Discussion: add, do not repeat.** Your post must contribute something new to what the two classmates said. A specific example from your experience or a consequence nobody mentioned is worth more than a restatement.\n- **Two-minute proofread, every time.** Verb forms, articles, subject–verb agreement, plural -s. Practise it as a fixed final step in every timed response.\n\nThe [Email and Discussion Templates](/guide-email-and-discussion-templates) guide gives adaptable structures and annotated model answers."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:13')::uuid, 'rich_text', 'Speaking: what separates 4 from 5', 13, '{"markdown":"Speaking has **Listen and Repeat** (7 sentences) and **Take an Interview** (4 questions, 45 seconds each). Every one of the 11 items is scored 0–5, so the section has 55 raw points and **Listen and Repeat carries 35 of them**. The descriptors:\n\n- In Listen and Repeat, a 5 is an exact, fully intelligible repetition; a 4 keeps the meaning but changes or drops small words, tense or number markers.\n- In the interview, a 5 is on topic and well elaborated, at a good conversational pace with natural pauses, easily intelligible, with rhythm and intonation that carry meaning. A 4 is elaborated but may lack connectors, has some pausing that affects flow, and grammar adequate for general meanings.\n\nAt section level, ETS describes B2 speakers as producing stretches of speech at an even tempo but hesitating while searching for patterns, and C1 speakers as fluent and spontaneous, almost effortless, with broader grammar and less common vocabulary used appropriately."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:14')::uuid, 'rich_text', 'Speaking: the moves that work at this level', 14, '{"markdown":"- **Exactness drill for Listen and Repeat.** Repeat, record, then compare word by word with the script. Count function words you dropped (*the, a, of, to, have*) and endings you lost (*-ed, -s*). Those are the difference between a 4 and a 5 on each sentence.\n- **Chunk the long sentences.** The sentences grow longer through the task. Hear them as two or three meaning groups, not as a string of words; the [Listen and Repeat](/speaking-listen-and-repeat) module explains thought groups.\n- **45-second answer shape.** Direct answer first, then a reason, then a specific example, then a closing line. The [Interview Answer Frameworks](/guide-interview-answer-frameworks) guide gives frameworks for all four interview questions and model answers at three levels.\n- **Connectors out loud.** The 4 descriptor mentions missing connectors. Rehearse a small set until they are automatic: *the main reason is*, *for example*, *on the other hand*, *which means that*.\n- **Record and listen back daily.** Five minutes. You will hear the pauses and false starts that you cannot hear while speaking."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:15')::uuid, 'rich_text', 'Weekly targets for an eight-week push', 15, '{"markdown":"This is a template. Shift hours toward your priority section, but keep every section in contact every week. Schood''s own [Eight-Week Standard plan](/plans/eight-week-standard) turns it into daily tasks.\n\n| Week | Main work | Hours | Checkpoint |\n|---|---|---|---|\n| 1 | Baseline mock, profile, error log set up, first drills | 8–10 | Log has 30+ entries |\n| 2 | Priority section drills; daily Complete the Words | 8–10 | Priority drill accuracy measured |\n| 3 | Priority section timed sets; productive-skill feedback | 9–11 | Two timed writing tasks reviewed |\n| 4 | Section mock of priority section; review | 9–11 | Section band vs baseline |\n| 5 | Second priority; maintain the first | 9–11 | Error categories shrinking |\n| 6 | Full mock; re-profile | 10–12 | Full mock bands recorded |\n| 7 | Target the two weakest error categories | 9–11 | Repeat-error rate down |\n| 8 | Final full mock and test-day rehearsal | 8–10 | Decision: test, or extend |\n\nHours are guidance for a learner studying alongside school or work. They are not a promise of results; the right number is the one you can sustain every week."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:16')::uuid, 'rich_text', 'The error log', 16, '{"markdown":"The error log is the most useful tool in this guide. Keep it as a spreadsheet or a notebook with these columns:\n\n| Field | What to write |\n|---|---|\n| Date and source | \"Mock 2, Reading\" or \"Drill, Email 4\" |\n| Task type | Complete the Words, Daily Life, Academic Passage, Choose a Response, and so on |\n| What happened | The question, your answer, the correct answer, or the sentence you said |\n| Category | One label from the category list below |\n| Why | One sentence: what you thought, and what you should have noticed |\n| Fix | The drill that targets it, with a date to repeat it |\n\nRules that make the log work:\n\n- **One miss, one line.** Do not summarise five misses as \"vocabulary problems\".\n- **Write the why in your own words.** \"Did not see *however* changed the direction\" is useful; \"careless\" is not.\n- **Every entry gets a fix with a date.** An entry without a fix is a diary, not a log."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:17')::uuid, 'rich_text', 'Error categories that matter at this level', 17, '{"markdown":"Use a small fixed set of labels so patterns show up when you count them:\n\n- **R-form:** Complete the Words word form (suffix, ending, part of speech)\n- **R-vocab:** did not know the word or its meaning in context\n- **R-purpose:** missed why a paragraph or sentence exists\n- **R-infer:** chose a stated detail when the question asked for implication\n- **L-reply:** wrong reply type in Choose a Response\n- **L-detail:** missed a changed detail, time or action\n- **L-structure:** lost the organisation of a talk\n- **W-grammar:** verb form, agreement, article, plural\n- **W-word:** vague or wrong word choice, wrong collocation\n- **W-task:** missed a bullet in the email or did not add to the discussion\n- **S-exact:** dropped or changed words in Listen and Repeat\n- **S-flow:** long pauses, restarts, missing connectors\n- **S-develop:** answer too short or too general\n- **T-time:** ran out of time or rushed the end\n\nAt the end of each week, count entries per label. **Your two biggest labels are next week''s drill focus.**"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:18')::uuid, 'rich_text', 'The weekly review session', 18, '{"markdown":"Block one 60-minute session at the end of every week. Do it in this order:\n\n1. **Count the log.** Totals per category this week and last week.\n2. **Pick two categories.** The two largest, unless one is already shrinking fast.\n3. **Re-do five old misses** from those categories without looking at the answers.\n4. **Plan next week:** which drills, which days, which timed sets.\n5. **Write one sentence of evidence** about progress, using numbers you actually measured (for example \"Build a Sentence: 7/10 → 9/10 across two sets\").\n\nNever write a progress note you cannot back with a measured number. If you did not measure, write \"not measured yet\" and fix that next week."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:19')::uuid, 'rich_text', 'Checkpoints and decision rules', 19, '{"markdown":"Plans fail quietly. These rules make you notice:\n\n- **After two weeks on a priority section with no change in drill accuracy:** change the drill, not the hours. The drill is not targeting the real error.\n- **If a section band does not move across two full mocks four weeks apart:** go back to the error log and re-label the last 30 entries. Mislabelled errors are the usual cause.\n- **If the overall average is within a quarter band of 5:** spend the next fortnight on the section with the cheapest next half band, which is usually Writing or Speaking for Profile A and C learners.\n- **If one section drops while you push another:** add two maintenance sessions a week for the dropping section before continuing.\n- **If a test date is fixed and your last full mock is below 4.5 overall two weeks before it:** decide calmly whether to keep the date or reschedule. ETS''s bulletin requires reschedules at least four full days before the test."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:20')::uuid, 'rich_text', 'Using Schood for every step', 20, '{"markdown":"- **[TOEFL simulator, full exam](https://toefl.schood.online/full-exam):** baseline and checkpoint mocks in the real section order.\n- **[Simulator practice](https://toefl.schood.online/practice):** section and task-type sets for weekly drills.\n- **[Review](https://toefl.schood.online/review):** go back through past sessions and copy every miss into the error log.\n- **[Your dashboard](/dashboard):** set your target and deadline so the plan recommendations reflect them.\n\nSchood mock bands are practice estimates, built to follow the ETS format and descriptors. They are useful for tracking direction. Your official band comes only from ETS."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:21')::uuid, 'rich_text', 'Common plateaus at 4.5', 21, '{"markdown":"- **The \"almost\" Writing plateau.** Emails and posts are on task but full of small errors. Fix: the two-minute proofread and a personal list of your five most frequent grammar errors, checked every time.\n- **The fast-but-vague Speaking plateau.** Answers are fluent but general (\"it is very important for many people\"). Fix: one specific example per answer: a name, a place, a time, a number you actually know.\n- **The safe-vocabulary plateau.** Writing uses only words you are sure of, so it never shows precise word choice. Fix: one upgrade per paragraph, chosen during the proofread.\n- **The router-error plateau.** Reading and Listening misses cluster early in the section. Fix: slow down very slightly at the start; accuracy in the first stage matters more than speed.\n- **The comfort-accent plateau.** Listening misses cluster on one accent. Fix: accent rotation for three weeks."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:22')::uuid, 'callout', 'Mistakes that waste weeks', 22, '{"label":"Practising what you are already good at","body":"The most common reason for a stuck band is that practice time goes to the comfortable section. If your error log says Speaking, but your week was mostly reading passages, you will feel busy and stay at 4.5. Let the counts in the log, not your mood, decide the week."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:23')::uuid, 'faq', 'Frequently asked questions', 23, '{"items":[{"question":"Can I reach band 5 overall with one section at 4?","answer":"Yes, arithmetically. For example 5.5, 5.5, 4 and 4 average 4.75, which rounds to 5. But check whether your institution sets section minimums; many do, and a section at 4 may fail them even when the overall passes."},{"question":"Is band 5 the same as the old 95?","answer":"ETS''s comparison table lists 95+ as the 0–120 total comparable to an overall band 5. During the two-year transition your score report shows both, so you can check against either requirement without converting anything."},{"question":"Should I work on all four sections every week?","answer":"Yes, but not equally. Put most hours on the priority section and keep the others in short maintenance sessions so they do not slip."},{"question":"How many full mocks should I take in eight weeks?","answer":"Three is a good number: a baseline, one in the middle, and one near the end. More mocks without review do not help; the review is where the learning happens."},{"question":"My Speaking band is the lowest of my four. Is that unusual?","answer":"No. In ETS''s figures for 2024 test takers converted to the new scale, the average Speaking band (3.96) was lower than the averages for Reading (4.59), Listening (4.77) and Writing (4.37). It is a common profile, and Speaking is a section where specific, practisable habits (exact repetition, answer structure, connectors) are what the scoring guide describes."}]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-4-to-5-roadmap:24')::uuid, 'cta_strip', 'Your next step', 24, '{"label":"Turn the roadmap into a schedule","primary_text":"Open your dashboard","primary_url":"/dashboard","secondary_text":"Take a full mock in the simulator","secondary_url":"https://toefl.schood.online/full-exam","surface":"premium"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb)
) as v(id, block_type, heading, sort_order, content, metadata)
join public.toefl_playbook_pages p on p.locale_code = 'en' and p.slug = 'guide-band-4-to-5-roadmap'
on conflict do nothing;

-- guide-band-5-to-6-roadmap: 25 sections
insert into public.toefl_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, p.id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (values
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:1')::uuid, 'rich_text', 'Who this roadmap is for', 1, '{"markdown":"This guide is for candidates who already score **band 5 or 5.5 overall** on a recent TOEFL iBT or on full mocks in the [Schood simulator](https://toefl.schood.online/full-exam), and who want **band 6**, the top of the 2026 scale and the level ETS aligns to CEFR **C2**.\n\nAt this level the usual advice stops working. You already know the format, your grammar is mostly accurate, and you finish sections on time. What separates 5.5 from 6 is **precision and consistency**: fewer misses on the hardest items, fewer small slips in writing and repetition, and speech that is not just fluent but exact and well organised.\n\nBefore you start, answer one question honestly: **does your goal actually require 6?** Most institutions publish requirements below the top band, and ETS sets no pass mark. A 6 is a strong signal, but if your target asks for 5 with section minimums, the better use of your time may be protecting those minimums. If you do need 6 (some scholarships, competitive programmes, or personal goals), this roadmap is for you."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:2')::uuid, 'checklist', 'What you will be able to do', 2, '{"items":["Explain exactly what a band 6 overall requires arithmetically","Locate the task types where C2-level evidence is gathered","Run a precision audit on two full mocks and measure your variance","Use advanced drills for stance, style, implication and exact repetition","Write with qualifying devices that remove ambiguity, as the C2 descriptor describes","Decide, with evidence, when you are ready to book and when MyBest scores help"]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:3')::uuid, 'rich_text', 'Band 6 on the 2026 scale', 3, '{"markdown":"On ETS''s 1–6 scale, **band 6 corresponds to CEFR C2** in every section and overall, and **5–5.5 corresponds to C1**. During the two-year transition, the score report also shows a comparable 0–120 total. ETS''s comparison table gives:\n\n| Band | Reading (0–30) | Listening (0–30) | Writing (0–30) | Speaking (0–30) | Total |\n|---|---|---|---|---|---|\n| 6 | 29–30 | 28–30 | 29–30 | 28–30 | 114+ |\n| 5.5 | 27–28 | 26–27 | 27–28 | 27 | 107+ |\n| 5 | 24–26 | 22–25 | 24–26 | 25–26 | 95+ |\n\nRead the top row carefully. On the old scale, band 6 Reading starts at **29 out of 30**. That tells you something important about the new top band: it represents performance with very little room for error. You are not trying to get \"a bit better\"; you are trying to remove most of your remaining misses."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:4')::uuid, 'rich_text', 'The arithmetic of an overall 6', 4, '{"markdown":"The overall band is the average of the four sections rounded to the nearest half band, and ETS''s published example shows a quarter-band average rounding up (5.25 becomes 5.5). So an overall 6 needs an average of **5.75 or more**.\n\n| Reading | Listening | Writing | Speaking | Average | Overall |\n|---|---|---|---|---|---|\n| 6 | 6 | 6 | 6 | 6.00 | 6 |\n| 6 | 6 | 6 | 5 | 5.75 | 6 |\n| 6 | 6 | 5.5 | 5.5 | 5.75 | 6 |\n| 6 | 5.5 | 5.5 | 5.5 | 5.625 | 5.5 |\n| 6 | 6 | 6 | 4.5 | 5.625 | 5.5 |\n\nTwo practical conclusions:\n\n- **You need at least two sections at 6**, and the other two at 5.5 or above, or three at 6 and one at 5.\n- **Any section at 4.5 makes an overall 6 impossible**, even with three perfect sections. If one section is below 5, fix that before anything else."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:5')::uuid, 'rich_text', 'Where C2 evidence lives in the test', 5, '{"markdown":"ETS''s blueprint gives a CEFR range for every task type. Not every task is built to reach C2:\n\n| Task type | CEFR range in the blueprint |\n|---|---|\n| Complete the Words | B1–C1+ |\n| Read in Daily Life | A1–C1 |\n| Read an Academic Passage | B1–C2 |\n| Listen and Choose a Response | A1–B2 |\n| Listen to a Conversation | A2–C1 |\n| Listen to an Announcement | A2–C1 |\n| Listen to an Academic Talk | A2–C2 |\n| Build a Sentence | A1–C2 |\n| Write an Email | B1–C2 |\n| Write for an Academic Discussion | B1–C2 |\n| Listen and Repeat | A1–C2 |\n| Take an Interview | A1–C2 |\n\nWhat this means for a band 6 candidate:\n\n- In **Reading and Listening**, the tasks with the highest ceiling are the **academic passage and the academic talk**. You cannot afford misses on the easier task types either, but your extra study hours should go to the hardest academic material.\n- In **Writing and Speaking**, every task can show C2, so the gains come from raising the quality of every response, especially Listen and Repeat and Build a Sentence, which together carry a large share of raw points (35 of 55 in Speaking and 10 of 20 in Writing, per the blueprint)."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:6')::uuid, 'rich_text', 'Step 1: the precision audit', 6, '{"markdown":"At band 5.5, one mock is not enough evidence. Take **two full mocks** in the [simulator](https://toefl.schood.online/full-exam), at least five days apart, under test conditions. Then build an audit table:\n\n| Measure | Mock A | Mock B |\n|---|---|---|\n| Section bands | | |\n| Reading misses by task type | | |\n| Listening misses by task type | | |\n| Build a Sentence score (of 10) | | |\n| Listen and Repeat sentences with any change | | |\n| Email and discussion feedback, top issue | | |\n| Interview: answers under 35 seconds of content | | |\n\nThen ask three questions:\n\n1. **Where are the misses?** At this level, misses usually concentrate in two or three task types.\n2. **Are they the same misses?** If Mock A and Mock B fail in the same places, you have a skill gap. If they fail in different places, you have a **consistency** problem.\n3. **What is the variance?** If a section moves a half band between two mocks, that section is not secure, even if one result was a 6."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:7')::uuid, 'rich_text', 'Reading: C1 versus C2', 7, '{"markdown":"ETS''s descriptors describe a **C1 reader** as handling lengthy, complex texts and identifying finer points of detail, including attitudes and implied or stated opinions. A **C2 reader** understands a broad range of long and complex texts and appreciates **subtle distinctions of style**, identifying both implicit and explicit meaning.\n\nIn practice the C1 to C2 difference in Reading appears in questions that ask:\n\n- why the author includes a particular example or sentence\n- how two paragraphs relate (contrast, concession, elaboration, evidence for a claim)\n- what a word means in this specific context, when its everyday meaning would mislead\n- what the author implies about a position without stating it\n\nC1 readers are usually right about **what** a text says and sometimes wrong about **why** it says it. C2 readers are reliable on both."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:8')::uuid, 'rich_text', 'Reading: advanced drills', 8, '{"markdown":"- **Stance mapping.** For every academic passage you practise, mark each claim as the author''s view, a reported view, or evidence. Then answer the questions. Many advanced misses come from choosing a reported view as the author''s.\n- **Function labels.** Write a one-word function next to each sentence: *claim, example, concession, contrast, consequence, definition*. When a question asks why something is mentioned, your label is usually the answer.\n- **Context-meaning drill.** Collect words whose usual meaning differs from their academic meaning (*account for, qualify, arrest, sound, treat, figure*). Write one sentence for each sense.\n- **Complete the Words at speed and 100% accuracy.** At band 6, Complete the Words misses should be close to zero. Use the hardest paragraphs in the [Complete the Words Drills](/guide-complete-the-words-drills) guide under a strict time limit and treat any miss as a priority log entry.\n- **Read above the test.** Add 20 minutes a day of long-form academic or high-quality journalistic reading. The test''s academic passages are around 200 words; reading much longer, denser texts makes them feel short."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:9')::uuid, 'rich_text', 'Listening: C1 versus C2', 9, '{"markdown":"ETS describes a **C1 listener** as skilled at using contextual, grammatical and lexical cues to infer attitude, mood and intentions and to anticipate what comes next, while possibly needing to confirm occasional details with an unfamiliar accent. A **C2 listener** makes appropriate inferences even when the links or implications are not made explicit.\n\nSo the C2 step is about **implicit connections**:\n\n- the speaker never says \"therefore\", but the second point is a consequence of the first\n- the speaker mentions an example without saying what it illustrates\n- the tone (hedging, mild irony, enthusiasm) changes the meaning of a literal statement\n- an announcement implies an action the listener must take without stating it as an instruction"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:10')::uuid, 'rich_text', 'Listening: advanced drills', 10, '{"markdown":"- **Silent-link drill.** Listen to an academic talk once, then write the logical relationship between each pair of points (cause, contrast, example, exception) even where no signal word was used. Check against the transcript.\n- **Tone labelling.** For short dialogues, label the speaker''s attitude in one word (*sceptical, reluctant, relieved, apologetic*). Choose a Response items often hinge on this.\n- **Unfamiliar-accent block.** Identify your weakest of North American, British and Australian English and give it two extra sessions a week for a month.\n- **Note economy.** At this level heavy notes can cost attention. Practise with notes limited to six words per talk: topic, purpose, two key terms, structure, conclusion.\n- **No-replay discipline.** In practice, never replay audio before answering. The test plays each recording once."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:11')::uuid, 'rich_text', 'Writing: C1 versus C2', 11, '{"markdown":"ETS describes **C1 writing** as using a broad range of complex structures flexibly, with consistent layout and punctuation, precisely qualifying opinions by degree of certainty, and expressing strong disagreement diplomatically. **C2 writing** uses comprehensive mastery to formulate thoughts precisely, give emphasis, differentiate and eliminate ambiguity, conveys finer shades of meaning with qualifying devices (adverbs of degree, clauses that limit a claim), and shows awareness of connotation.\n\nOn the task scoring guides, a 5 on the email or the discussion already requires precise, idiomatic word choice and almost no errors beyond typical timed slips. The band 6 writer gets that 5 **consistently**, on both tasks, every time, and adds near-perfect Build a Sentence accuracy."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:12')::uuid, 'rich_text', 'Writing: the precision toolkit', 12, '{"markdown":"These are the tools the C2 descriptor points to. Practise them until they appear naturally:\n\n- **Degree adverbs:** *largely, partly, marginally, considerably, scarcely* instead of *very* and *really*.\n- **Limiting clauses:** *at least in the short term*, *provided that funding continues*, *except where students already work*.\n- **Precise contrast:** *whereas* (two parallel facts), *although* (a concession), *yet* (an unexpected result), *by contrast* (two separate cases).\n- **Emphasis by structure:** *What matters most is…*, *It is the cost, not the idea, that worries me.*\n- **Connotation choices:** *frugal* versus *stingy*, *persistent* versus *stubborn*, *modest* versus *small*. Choose the word whose attitude you intend.\n\nEach of these makes a sentence say exactly one thing. That is what \"eliminate ambiguity\" means in practice."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:13')::uuid, 'rich_text', 'Writing: a before-and-after rewrite', 13, '{"markdown":"A discussion sentence at C1:\n\n> Online classes are good for students because they are flexible, but they also have some problems with motivation.\n\nThe same idea at C2:\n\n> Online classes suit students who already manage their time well; for those who rely on the structure of a timetable, the same flexibility can quietly erode motivation.\n\nWhat changed:\n\n- **\"good for students\"** became a claim limited to a specific group of students.\n- **\"some problems\"** became a named mechanism: flexibility eroding motivation.\n- The semicolon and **\"the same flexibility\"** link the two halves logically instead of with a vague *but*.\n- **\"quietly erode\"** adds a precise shade of meaning (gradual, unnoticed) that *some problems* did not.\n\nRun this rewrite on one sentence from every practice response for four weeks. Keep the before-and-after pairs in your log."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:14')::uuid, 'rich_text', 'Speaking: C1 versus C2', 14, '{"markdown":"ETS describes **C1 speaking** as fluent and spontaneous, almost effortless, using complex structures and less common vocabulary appropriately, with the full range of phonological features controlled well enough for intelligibility. **C2 speaking** flows naturally and smoothly at length, pauses only to find precisely the right word or an example, formulates thoughts precisely without restricting what the speaker wants to say, and gives clear, elaborate and often memorable descriptions.\n\nOn the tasks:\n\n- **Listen and Repeat:** the C2 descriptor in the blueprint describes repetition that is fluent and intelligible with clear segmentation of meaning. A score of 5 on each sentence requires an exact repetition, so at band 6 you need **all seven sentences exact**, including the longest ones.\n- **Take an Interview:** a 5 is on topic, well elaborated, at a good conversational pace, easily intelligible, with rhythm and intonation that convey meaning and accurate, varied language. ETS''s own 5-level samples contain natural fillers; band 6 is not about removing every *um*, it is about precise, organised content delivered with control."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:15')::uuid, 'rich_text', 'Speaking: advanced drills', 15, '{"markdown":"- **Longest-sentence drill.** Collect long academic or campus sentences of 15–20 words with relative clauses and compound verbs. Hear once, repeat once, record, check word by word. Target: zero changes across ten sentences in a row.\n- **Precision interview answers.** For each practice question, give a 45-second answer that includes one limiting clause and one precise example (a real place, time or number you know). The [Interview Answer Frameworks](/guide-interview-answer-frameworks) guide shows band 6 model answers with commentary.\n- **Memorable detail.** End descriptive answers with one concrete image (\"the bus that never arrives before 8:10\"). The C2 descriptor mentions often memorable descriptions; one specific detail does more than three general adjectives.\n- **Intonation for contrast.** Practise stressing the contrasting words in sentences like \"It''s not the *cost*, it''s the *time*.\" Rhythm and intonation that carry meaning are explicitly in the scoring guide."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:16')::uuid, 'rich_text', 'Vocabulary depth for C2', 16, '{"markdown":"At band 6, vocabulary is less about knowing more words and more about knowing each word **deeply**: its family, its partners, its register and its attitude. ETS''s C2 descriptors mention a broad lexical repertoire including idiomatic expressions and awareness of connotation, and the C1 to C2 reading step is about subtle distinctions of style.\n\nBuild depth with four questions for every new academic word:\n\n1. **Family:** what are its noun, verb, adjective and adverb forms? (*viable, viability*; *contend, contention, contentious*)\n2. **Partners:** which words does it usually appear with? (*a contentious issue*, *raise a concern*, *draw a distinction*)\n3. **Register:** is it formal, neutral or informal? (*commence* versus *start*; *a lot of* versus *a substantial number of*)\n4. **Attitude:** does it carry a positive or negative shade? (*ambitious* versus *overambitious*; *assertive* versus *pushy*)\n\nKeep a depth notebook with one line per word answering all four. Review it in Complete the Words drills (family), in your writing (partners and register) and in interview answers (attitude). Twenty deep entries a week do more at this level than a hundred translations."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:17')::uuid, 'rich_text', 'Listen and Repeat at full length', 17, '{"markdown":"The final Listen and Repeat sentences are the longest and most complex: the blueprint describes progression toward compound verbs, dependent and relative clauses, and complex noun phrases. Band 5.5 speakers often repeat the first five sentences exactly and lose a function word or an ending in the last two.\n\n- **Practise the end of the task, not the start.** Build a bank of sentences of 15–22 words and spend most of your repetition time there.\n- **Hold the structure, not the words.** Before you speak, identify the main clause and the attached clause: *The form, which you can find at the front desk, / must be signed by your advisor.* Structure is easier to remember than a string of words.\n- **Keep the endings.** Final -s, -ed and -ing disappear under pressure. Check them first when you compare your recording with the script.\n- **Measure in sets of seven.** Score each set as the number of exact repetitions out of seven, and track the number weekly."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:18')::uuid, 'rich_text', 'Reducing variance', 18, '{"markdown":"Many band 5.5 candidates already produce band 6 performances on some days. The goal is to produce them **on test day**. Variance comes from three sources:\n\n- **Fatigue:** the test runs for roughly two hours with no scheduled breaks, and Speaking comes last. Practise full mocks at your test time of day.\n- **Early errors:** in the adaptive sections, the first stage decides the difficulty of the second. Build a habit of extra care in the first items of Reading and Listening.\n- **Unchecked writing:** most C1 writers can produce near-error-free text when they proofread. The ones who do not reach 6 skip the proofread when time is short. Make the final two minutes of each writing task non-negotiable.\n\nMeasure variance directly: keep the results of every full mock and every section mock in one table and look at the range, not just the best result."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:19')::uuid, 'rich_text', 'Weekly targets for a six- to eight-week push', 19, '{"markdown":"| Week | Main work | Hours | Checkpoint |\n|---|---|---|---|\n| 1 | Two full mocks; precision audit | 8–10 | Audit table complete |\n| 2 | Weakest section: advanced drills | 9–11 | Misses per task type counted |\n| 3 | Writing precision toolkit; daily rewrites | 9–11 | Two timed tasks reviewed line by line |\n| 4 | Section mocks for the two weakest sections | 9–11 | Both sections at 5.5 or above |\n| 5 | Listen and Repeat exactness; interview precision | 9–11 | Ten exact long sentences in a row |\n| 6 | Full mock; variance check | 10–12 | Range across mocks ≤ half band |\n| 7–8 | Optional: repeat weeks 4–6 on the remaining gap | 9–11 | Decision rule below |\n\nFor a structured daily version, start from the [Eight-Week Standard plan](/plans/eight-week-standard) and replace its drill tasks with the advanced drills in this guide."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:20')::uuid, 'rich_text', 'Advanced error-log fields', 20, '{"markdown":"Add three fields to the standard log described in the [Band 4 to 5 Roadmap](/guide-band-4-to-5-roadmap):\n\n- **Confidence (1–3):** how sure you were when you answered. A wrong answer at confidence 3 is a misconception; at confidence 1 it is a guess. They need different fixes.\n- **Near-miss:** questions you answered correctly but only after changing your answer or spending too long. These are tomorrow''s errors.\n- **Level of the item:** easy, medium or hard as you judged it. At band 6, misses on easy items are the most expensive and the most fixable.\n\nReview weekly: count confident-wrong answers separately. If they are more than a handful, you have specific misconceptions to correct, usually in vocabulary meaning or in how you interpret author stance."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:21')::uuid, 'rich_text', 'Decision rules', 21, '{"markdown":"- **Book the test** when your last two full mocks both average 5.75 or above, and no section in either mock is below 5.5.\n- **Keep preparing** if one mock reaches 6 and the other is 5.5: that is variance, not readiness. Spend two weeks on the source of the variance and test again.\n- **Change approach** if a section has not moved across three weeks of targeted drills. At this level, that usually means the drill is too easy. Raise the difficulty of the material, not the number of hours.\n- **Consider MyBest** if you already have an official result with strong sections. ETS''s score report includes MyBest scores, the highest section scores from valid tests in the last two years. Whether an institution accepts them is the institution''s decision, so check first; the [Retake and MyBest Strategy](/retake-and-mybest-strategy) module explains the trade-offs.\n- **Respect the retake rule.** ETS allows unlimited attempts but not more than one test in any three-day period."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:22')::uuid, 'rich_text', 'Protecting the score on test day', 22, '{"markdown":"At band 6, test day is mostly about not losing points you already own:\n\n- Take the first items of Reading and Listening a little slower than feels necessary.\n- Do not change a Reading answer unless you can name the exact words that prove the new one.\n- In Writing, start the proofread with two minutes left, whatever happens.\n- In Listen and Repeat, wait for the whole sentence before you start speaking, then speak it in meaning groups.\n- If the score summary at the end offers you the choice to report or cancel, decide by your plan, not by your mood. ETS shows unofficial Reading and Listening scores at that point; Writing and Speaking are not shown yet."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:23')::uuid, 'callout', 'The wrong target', 23, '{"label":"Perfection is not the requirement","body":"ETS''s own score-5 sample responses contain small errors and natural fillers. Band 6 rewards precise, controlled, well-organised language with errors only of the kind a capable writer or speaker makes under time pressure. Chasing zero imperfections makes you slower and more hesitant, which costs more than the errors you are trying to avoid."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:24')::uuid, 'faq', 'Frequently asked questions', 24, '{"items":[{"question":"Is band 6 required by many universities?","answer":"ETS publishes no pass mark, and requirements vary by institution and programme. Many requirements sit below the top band. Check your exact programme''s page and any section minimums before committing months to a 6."},{"question":"Can I get an overall 6 with Speaking at 5?","answer":"Yes, if the other three sections are all 6: the average is 5.75, which rounds to 6. With Speaking at 5 and any other section at 5.5, the average falls to 5.625 and the overall is 5.5."},{"question":"Do Reading and Listening at band 6 mean zero mistakes?","answer":"ETS does not publish raw-to-band tables for the 2026 sections, so nobody can tell you an exact number. The old-scale comparison (29–30 of 30 for Reading) suggests the margin is very small. Plan for near-perfect accuracy."},{"question":"Should I request a score review if I miss band 6 by half a band?","answer":"ETS allows a review of Speaking and/or Writing within 30 days of the test, for a fee, and only if you have not already sent scores to an institution. A review can raise or lower the score. Reading and Listening cannot be reviewed."},{"question":"How do I know if my mock result is reliable?","answer":"Treat any single mock as one data point. Two or more full mocks, taken under the same conditions, are much better evidence, and the spread between them tells you how secure the result is."}]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-band-5-to-6-roadmap:25')::uuid, 'cta_strip', 'Your next step', 25, '{"label":"Start the precision audit","primary_text":"Take full mock A","primary_url":"https://toefl.schood.online/full-exam","secondary_text":"Open your dashboard","secondary_url":"/dashboard","surface":"premium"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb)
) as v(id, block_type, heading, sort_order, content, metadata)
join public.toefl_playbook_pages p on p.locale_code = 'en' and p.slug = 'guide-band-5-to-6-roadmap'
on conflict do nothing;

-- guide-complete-the-words-drills: 42 sections
insert into public.toefl_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, p.id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (values
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:1')::uuid, 'rich_text', 'What this guide adds', 1, '{"markdown":"The public [Complete the Words](/reading-complete-the-words) module explains the task. This guide is the training book. It gives you:\n\n- a **five-step routine** that turns every blank into a small logic problem instead of a guess\n- the **clues** that solve most blanks: the visible letters, the number of missing letters, the grammar slot, the word family and the collocation\n- **twelve original paragraphs**, written for Schood in the format ETS describes, graded from B1 to C1+\n- an **answer key for every paragraph** with a short explanation for each of the 120 missing words\n\nWork through the drills in order. Each level adds harder vocabulary and longer, more academic sentences. Do not open an answer key until you have written all ten answers for that paragraph."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:2')::uuid, 'checklist', 'What you will be able to do', 2, '{"items":["Use the visible letters and the number of blanks to narrow every gap to a few candidates","Decide the part of speech a gap needs from its position in the sentence","Choose the right ending from a word family: -tion, -ment, -ive, -al, -ly, -ed, -ing","Recognise fixed phrases and collocations that complete themselves","Avoid the spelling traps that cost points even when you know the word","Review your misses by error type and build your own drills"]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:3')::uuid, 'rich_text', 'How the task works', 3, '{"markdown":"ETS''s overview of the updated test describes Complete the Words like this, in summary:\n\n- You see an **academic paragraph of about 70–100 words**.\n- The **first sentence is complete**.\n- After that, **the second half of every second word is removed**, and you type the missing letters.\n- **Each paragraph has 10 words with missing letters.**\n\nIn the blueprint, Complete the Words sits in the Reading claim \"process academic written texts for meaning and form\", targets **CEFR B1 to C1+**, and accounts for **30 target items**, each worth a maximum of 1 point. It assesses word-ordering rules, lexical knowledge and reading comprehension together, which is why grammar and vocabulary both matter.\n\nReading is two-stage adaptive, so the paragraphs you see later depend on how you did earlier. The blueprint estimates the first stage at 18–21 minutes and the second at 9 minutes for the whole Reading section; ETS does not publish a separate time for each paragraph."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:4')::uuid, 'rich_text', 'The letter rule', 4, '{"markdown":"Look closely at ETS''s sample paragraph and a pattern appears in every gap: **the visible part is the first half of the word, rounded down, and each missing letter is shown as its own blank.**\n\n| Word length | Visible | Missing | Example |\n|---|---|---|---|\n| 2 | 1 | 1 | is → i + s |\n| 4 | 2 | 2 | from → fr + om |\n| 5 | 2 | 3 | might → mi + ght |\n| 6 | 3 | 3 | record → rec + ord |\n| 7 | 3 | 4 | however → how + ever |\n\nThis gives you two clues before you even think about meaning:\n\n- **The visible letters** tell you how the word starts.\n- **The number of blanks** tells you its exact length. If the visible part is *bec* and there are three blanks, the word has six letters: *became*, not *because*.\n\nSchood''s drills below follow the same rule, so you can practise counting blanks."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:5')::uuid, 'rich_text', 'The five-step routine', 5, '{"markdown":"Use the same five steps for every blank until they are automatic:\n\n1. **Read the first sentence fully.** It sets the topic and often contains the word family you will need later (*printing* in sentence one, *printed* in a blank).\n2. **Read the whole gapped sentence once** before filling anything. Many gaps are decided by a word that comes after them.\n3. **Name the slot:** noun, verb, adjective, adverb, preposition, article, pronoun or conjunction.\n4. **Generate candidates** from the visible letters and the blank count, then choose the one that fits the slot, the grammar (number, tense) and the meaning.\n5. **Check the form:** ending, agreement and spelling. Then move on. Return to doubtful gaps only if you have time.\n\nThe most common mistake is jumping to step 4 without steps 2 and 3. A word can start with the right letters, have the right length and still be the wrong part of speech."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:6')::uuid, 'rich_text', 'Clue 1: what the slot needs', 6, '{"markdown":"Position in the sentence tells you the part of speech:\n\n- **After an article or determiner** (*a, the, this, each, their*): a noun, or an adjective followed by a noun.\n- **After a subject, before an object:** a verb, and its form must agree with the subject.\n- **Between *be* or *have* and something else:** a participle (*been, revised, caused*) or an adjective.\n- **Before an adjective or a past participle:** often an adverb ending in *-ly* (*widely documented, relatively abundant*).\n- **Before a noun phrase that expresses time, place or means:** a preposition (*during, through, from*).\n- **At the start of a clause after a comma:** a conjunction or relative word (*while, which, whether*).\n\nWhen you are unsure, say the sentence with a placeholder: \"the ___ rock\". A placeholder that is clearly a describing word tells you the gap is an adjective."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:7')::uuid, 'rich_text', 'Clue 2: word families and suffixes', 7, '{"markdown":"Many Complete the Words gaps at B2 and above test **which form of a word family** fits. Learn endings by the job they do:\n\n| Job | Common endings | Examples |\n|---|---|---|\n| Noun (idea or process) | -tion, -sion, -ment, -ence, -ance, -ity, -ness | assumption, achievement, difference, capacity |\n| Noun (person) | -er, -or, -ist, -ant, -ee | worker, merchant, employee |\n| Adjective | -al, -ive, -ous, -ful, -able, -ible, -ic | neural, expensive, enormous, typical |\n| Adverb | -ly, -ally (after -ic) | widely, relatively, automatically, specifically |\n| Verb | -ize, -ify, -en, -ate | reorganize, specify, widen, indicate |\n| Participle | -ed, -ing | printed, competing, ruling, underlying |\n\nTwo fast checks:\n\n- **-ic adjectives take -ally as adverbs:** *automatic → automatically*, *specific → specifically*, *typical → typically*.\n- **Visible letters and blank count work together:** the visible part is always the first half of the whole word, so *difference* (10 letters) appears as *diffe* plus five blanks, while *different* (9 letters) would appear as *diff* plus five blanks. Together they fix the exact form."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:8')::uuid, 'rich_text', 'Clue 3: agreement and form', 8, '{"markdown":"When the slot is a verb or a noun, check the small endings:\n\n- **Third-person -s:** *it returns*, *one worker discovers*, *a glacier advances*.\n- **No -s with plural subjects:** *the algae provide*, *experiments indicate*, *humans possess*.\n- **Passive needs a participle:** *is caused by*, *be copied by*, *has been revised*.\n- **Plural nouns after quantity words and without articles:** *patches of flowers*, *free classes for adults*.\n- **Uncountable nouns stay singular:** *sediment*, *information*, *error* in *prone to error*.\n\nThese endings are exactly what a fast reader skips. Build the habit of checking the last letters of every completed word."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:9')::uuid, 'rich_text', 'Clue 4: collocations and fixed phrases', 9, '{"markdown":"A large share of gaps sits inside phrases that almost complete themselves once you know them:\n\n- **Fixed expressions:** *as well as*, *such as*, *known as*, *by hand*, *in partnership with*, *in response to*.\n- **Verb plus preposition:** *recover from*, *enrolled in*, *prone to*, *carry away*, *return to*.\n- **Verb plus noun:** *offer classes*, *perform a dance*, *raise wages*, *provide food*.\n- **Adjective plus noun:** *competing explanations*, *underlying rock*, *ruling families*, *default options*.\n\nWhen you meet a new academic word in your reading, record it with its common partner, not alone: write *prone to error*, not *prone*. Complete the Words rewards partners."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:10')::uuid, 'rich_text', 'Clue 5: the small words', 10, '{"markdown":"Every paragraph has gaps on short, frequent words. They look easy but cause careless misses because several words share the same visible letter:\n\n- **i + 1 blank:** *is, it, in, if*. Decide by grammar: a verb (*is*), a subject (*it*), a preposition (*in*) or a condition (*if*).\n- **a + 1 blank:** *an, as, at, am*. *An* before a vowel sound; *as* in *such as, known as, as well as*.\n- **o + 1 blank:** *of, on, or*. *Of* after quantities (*many of*) and in *the power of*.\n- **t + 2 blanks:** *the, two, too*. Usually *the*.\n- **th + 2 blanks:** *that, this, then, than, they*. *That* introduces a clause after *is, argue, predicts, indicate*.\n- **wh + 3 blanks:** *which, while, where*. *Which* begins a relative clause about a noun; *while* begins a contrasting or simultaneous clause."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:11')::uuid, 'rich_text', 'Spelling traps', 11, '{"markdown":"You can know the word and still lose the point. Watch for:\n\n- **Doubled letters:** *grammar*, *classes*, *occurred*, *committee*, *recommend*.\n- **y to i:** *copied*, *quantities*, *studies*.\n- **-ible or -able, -ence or -ance:** *possible, visible* but *available, reliable*; *difference, evidence* but *importance, performance*.\n- **Silent letters:** *through*, *scientist*, *knowledge*.\n- **American spelling:** ETS materials use American forms such as *recognize* and *organization*. Schood''s drills do the same: *reorganize*, *color*, *behavior*.\n\nType the full word in your head before typing the missing letters; spelling errors often come from typing only the end."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:12')::uuid, 'rich_text', 'Pacing', 12, '{"markdown":"ETS does not publish a time per paragraph, so set your own target from evidence:\n\n- In your first three drills, **time yourself** without pressure and write the time next to the score.\n- Then set a target about 20% faster than your average, and keep accuracy at 9 or 10 out of 10.\n- If accuracy drops below 8 out of 10 at the faster time, go back to the slower time for a week.\n\nThe point of speed is to leave time for the other Reading tasks. Accuracy on Complete the Words always comes first, because every item is worth the same single point."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:13')::uuid, 'rich_text', 'How to use the twelve drills', 13, '{"markdown":"- **Level 1 (B1), drills 1–3:** everyday academic topics, common words, mostly function words and simple forms.\n- **Level 2 (B2), drills 4–7:** more word-family and passive forms, fixed academic phrases.\n- **Level 3 (C1), drills 8–10:** longer academic words, adverbs, abstract nouns.\n- **Level 4 (C1+), drills 11–12:** dense academic prose with long nominalisations.\n\nFor each drill: write all ten answers, check against the key, then log every miss with its type (slot, family, agreement, collocation, small word, spelling). One drill a day for twelve days is a good rhythm; repeat the drills you scored below 9 a week later."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:14')::uuid, 'rich_text', 'Drill 1 (Level 1, B1): Public libraries', 14, '{"markdown":"Topic: how libraries have changed.\n\n> Public libraries have changed a great deal over the last fifty years. Many o\\_ them n\\_ \\_ lend lap\\_ \\_ \\_ \\_ as we\\_ \\_ as bo\\_ \\_ \\_, and so\\_ \\_ even of\\_ \\_ \\_ free cla\\_ \\_ \\_ \\_ for adu\\_ \\_ \\_ who wa\\_ \\_ to learn new skills. In small towns, the library is often the only place where people can use the internet without paying. Librarians say that visitor numbers have stayed high, although the reasons for visiting are different from the past.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:15')::uuid, 'rich_text', 'Drill 1 (Level 1, B1): Public libraries: answer key and explanations', 15, '{"markdown":"**Full text:** Public libraries have changed a great deal over the last fifty years. Many of them now lend laptops as well as books, and some even offer free classes for adults who want to learn new skills. In small towns, the library is often the only place where people can use the internet without paying. Librarians say that visitor numbers have stayed high, although the reasons for visiting are different from the past.\n\n1. **of** (o + *f*): Quantity pattern \"many of + pronoun\". With one blank after \"o\", only \"of\", \"on\" and \"or\" are possible, and only \"many of them\" is English.\n2. **now** (n + *ow*): An adverb between the subject and the verb \"lend\". \"New\" is an adjective and \"not\" would need \"do not\", so \"now\" is the only fit.\n3. **laptops** (lap + *tops*): Something a library lends, plural to match \"books\" in the same \"as well as\" pair.\n4. **well** (we + *ll*): The fixed expression \"as well as\", meaning \"and also\".\n5. **books** (bo + *oks*): Plural noun parallel with \"laptops\"; the traditional thing a library lends.\n6. **some** (so + *me*): A pronoun subject meaning \"some libraries\", followed by the verb \"offer\".\n7. **offer** (of + *fer*): Verb after the adverb \"even\"; \"offer classes\" is a common collocation.\n8. **classes** (cla + *sses*): Plural noun with no article; \"free classes for adults\" are lessons.\n9. **adults** (adu + *lts*): A person noun, signalled by \"who\"; plural because there is no article.\n10. **want** (wa + *nt*): Plural present verb after \"who\" (referring to adults), followed by \"to learn\"."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:16')::uuid, 'rich_text', 'Drill 2 (Level 1, B1): Sleep and memory', 16, '{"markdown":"Topic: why sleep may help learning.\n\n> Scientists have long wondered why the body needs so much sleep. One id\\_ \\_ is th\\_ \\_ sleep gi\\_ \\_ \\_ the br\\_ \\_ \\_ time t\\_ sort t\\_ \\_ information i\\_ collected dur\\_ \\_ \\_ the d\\_ \\_. In exper\\_ \\_ \\_ \\_ \\_ \\_, students who slept after learning a list of words remembered more of them the next morning than students who stayed awake. The effect was strongest for words that were difficult or unusual. Researchers now think that deep sleep and dreaming sleep may play different roles in this process.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:17')::uuid, 'rich_text', 'Drill 2 (Level 1, B1): Sleep and memory: answer key and explanations', 17, '{"markdown":"**Full text:** Scientists have long wondered why the body needs so much sleep. One idea is that sleep gives the brain time to sort the information it collected during the day. In experiments, students who slept after learning a list of words remembered more of them the next morning than students who stayed awake. The effect was strongest for words that were difficult or unusual. Researchers now think that deep sleep and dreaming sleep may play different roles in this process.\n\n1. **idea** (id + *ea*): A noun after \"One\" introducing a theory: \"One idea is that…\".\n2. **that** (th + *at*): \"is that + clause\" introduces the content of the idea. \"This\", \"then\" and \"than\" cannot introduce the clause.\n3. **gives** (gi + *ves*): The pattern \"give someone time to do something\"; third-person -s because the subject \"sleep\" is singular.\n4. **brain** (br + *ain*): The organ that sorts information; \"br\" plus three letters.\n5. **to** (t + *o*): \"time to + verb\", here \"time to sort\".\n6. **the** (t + *he*): Definite article: the information is specific, defined by \"it collected\".\n7. **it** (i + *t*): The relative clause needs a subject (\"the information it collected\"). \"Is\" would make \"sort the information is collected\", which is ungrammatical.\n8. **during** (dur + *ing*): A preposition of time before \"the day\".\n9. **day** (d + *ay*): \"During the day\" contrasts with sleep at night.\n10. **experiments** (exper + *iments*): A plural noun after \"In\" that introduces evidence. The word has eleven letters, so five are visible (\"exper\") and six are missing (\"iments\")."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:18')::uuid, 'rich_text', 'Drill 3 (Level 1, B1): How bees share directions', 18, '{"markdown":"Topic: animal communication.\n\n> Honeybees communicate with each other in a surprising way. When o\\_ \\_ worker disc\\_ \\_ \\_ \\_ \\_ rich pat\\_ \\_ \\_ \\_ of flo\\_ \\_ \\_ \\_, it ret\\_ \\_ \\_ \\_ to t\\_ \\_ hive a\\_ \\_ then perf\\_ \\_ \\_ \\_ a sh\\_ \\_ \\_ dance. T\\_ \\_ direction of the dance shows the other bees which way to fly, and the length of the dance tells them how far away the food is. Researchers first described this behavior in the twentieth century. Later studies showed that bees from different regions use slightly different versions of the dance.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:19')::uuid, 'rich_text', 'Drill 3 (Level 1, B1): How bees share directions: answer key and explanations', 19, '{"markdown":"**Full text:** Honeybees communicate with each other in a surprising way. When one worker discovers rich patches of flowers, it returns to the hive and then performs a short dance. The direction of the dance shows the other bees which way to fly, and the length of the dance tells them how far away the food is. Researchers first described this behavior in the twentieth century. Later studies showed that bees from different regions use slightly different versions of the dance.\n\n1. **one** (o + *ne*): A determiner before the singular noun \"worker\": a single bee. \"Our\" does not fit the meaning.\n2. **discovers** (disc + *overs*): A present-simple verb with -s after \"one worker\". Nine letters: \"disc\" plus five blanks. \"Discusses\" has the wrong meaning and length.\n3. **patches** (pat + *ches*): \"Patches of flowers\" are small areas; plural with \"rich\" and no article.\n4. **flowers** (flo + *wers*): What bees look for; plural after \"of\".\n5. **returns** (ret + *urns*): \"Return to\" a place; -s agrees with \"it\".\n6. **the** (t + *he*): Definite article before \"hive\", the bee''s home.\n7. **and** (a + *nd*): Joins two actions of the same subject: returns… and then performs.\n8. **performs** (perf + *orms*): \"Perform a dance\" is the collocation; -s agrees with \"it\". Eight letters: \"perf\" plus four.\n9. **short** (sh + *ort*): An adjective between \"a\" and \"dance\".\n10. **The** (T + *he*): The article that begins the new sentence, with a capital letter."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:20')::uuid, 'rich_text', 'Drill 4 (Level 2, B2): The urban heat island', 20, '{"markdown":"Topic: why cities are warmer.\n\n> Cities are often several degrees warmer than the countryside around them. This diffe\\_ \\_ \\_ \\_ \\_, known a\\_ the ur\\_ \\_ \\_ heat isl\\_ \\_ \\_ effect, i\\_ mainly cau\\_ \\_ \\_ by surf\\_ \\_ \\_ \\_ such a\\_ asphalt a\\_ \\_ concrete, wh\\_ \\_ \\_ absorb sunlight during the day and release it slowly at night. Planting trees and painting roofs in lighter colors can reduce the problem, but these measures work best when they are applied across entire neighborhoods. Some cities now require new buildings to include green roofs for this reason.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:21')::uuid, 'rich_text', 'Drill 4 (Level 2, B2): The urban heat island: answer key and explanations', 21, '{"markdown":"**Full text:** Cities are often several degrees warmer than the countryside around them. This difference, known as the urban heat island effect, is mainly caused by surfaces such as asphalt and concrete, which absorb sunlight during the day and release it slowly at night. Planting trees and painting roofs in lighter colors can reduce the problem, but these measures work best when they are applied across entire neighborhoods. Some cities now require new buildings to include green roofs for this reason.\n\n1. **difference** (diffe + *rence*): A noun after \"This\" that refers back to \"warmer\". The adjective \"different\" cannot follow \"This\" alone, and the blank count (five) gives \"-rence\".\n2. **as** (a + *s*): \"Known as\" means \"called\".\n3. **urban** (ur + *ban*): The fixed term \"urban heat island\", matching \"Cities\".\n4. **island** (isl + *and*): Part of the same fixed term.\n5. **is** (i + *s*): The passive \"is caused\"; singular to agree with \"This difference\".\n6. **caused** (cau + *sed*): Past participle in the passive \"caused by\".\n7. **surfaces** (surf + *aces*): A plural noun followed by examples (\"such as asphalt and concrete\").\n8. **as** (a + *s*): \"Such as\" introduces examples.\n9. **and** (a + *nd*): Joins the two examples.\n10. **which** (wh + *ich*): A non-defining relative clause after a comma takes \"which\", not \"that\". The plural verb \"absorb\" agrees with \"surfaces\"."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:22')::uuid, 'rich_text', 'Drill 5 (Level 2, B2): Printing and knowledge', 22, '{"markdown":"Topic: early printing in Europe.\n\n> The spread of printing in fifteenth-century Europe changed how knowledge traveled. Before pri\\_ \\_ \\_ \\_ books bec\\_ \\_ \\_ common, te\\_ \\_ \\_ had t\\_ be cop\\_ \\_ \\_ by ha\\_ \\_, which w\\_ \\_ slow, expe\\_ \\_ \\_ \\_ \\_ and pr\\_ \\_ \\_ to er\\_ \\_ \\_. Printing allowed identical copies to circulate widely, and this made it easier for scholars in different cities to compare their ideas. Historians still debate, however, how quickly ordinary people benefited from the change. Many people could not read, and books remained costly for decades.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:23')::uuid, 'rich_text', 'Drill 5 (Level 2, B2): Printing and knowledge: answer key and explanations', 23, '{"markdown":"**Full text:** The spread of printing in fifteenth-century Europe changed how knowledge traveled. Before printed books became common, texts had to be copied by hand, which was slow, expensive and prone to error. Printing allowed identical copies to circulate widely, and this made it easier for scholars in different cities to compare their ideas. Historians still debate, however, how quickly ordinary people benefited from the change. Many people could not read, and books remained costly for decades.\n\n1. **printed** (pri + *nted*): A participle used as an adjective, from the family of \"printing\" in sentence one. \"Printing books\" would describe the act, not the books.\n2. **became** (bec + *ame*): \"Become common\", past tense for history. The blank count matters: \"bec\" plus three blanks is \"became\"; \"because\" would need four.\n3. **texts** (te + *xts*): A plural subject for \"had to be copied\".\n4. **to** (t + *o*): \"Had to + verb\".\n5. **copied** (cop + *ied*): Passive past participle; \"y\" changes to \"i\" before -ed.\n6. **hand** (ha + *nd*): The fixed phrase \"by hand\".\n7. **was** (w + *as*): Singular, because \"which\" refers to the whole process of copying.\n8. **expensive** (expe + *nsive*): An adjective in a list of adjectives (\"slow, expensive and prone\"). The noun \"expense\" does not fit.\n9. **prone** (pr + *one*): \"Prone to\" means likely to suffer something.\n10. **error** (er + *ror*): \"Prone to error\" uses \"error\" as an uncountable idea, with no article."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:24')::uuid, 'rich_text', 'Drill 6 (Level 2, B2): Coral partnerships', 24, '{"markdown":"Topic: how coral reefs live.\n\n> Coral reefs cover only a small fraction of the ocean floor, yet they support an enormous variety of marine life. The re\\_ \\_ \\_ are bu\\_ \\_ \\_ by ti\\_ \\_ animals th\\_ \\_ live i\\_ partnership wi\\_ \\_ algae. T\\_ \\_ algae pro\\_ \\_ \\_ \\_ food thr\\_ \\_ \\_ \\_ photosynthesis, wh\\_ \\_ \\_ the corals offer shelter and nutrients in return. When water temperatures rise too far, this relationship breaks down, and the corals lose their color in a process called bleaching. Reefs can recover if conditions improve quickly enough.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:25')::uuid, 'rich_text', 'Drill 6 (Level 2, B2): Coral partnerships: answer key and explanations', 25, '{"markdown":"**Full text:** Coral reefs cover only a small fraction of the ocean floor, yet they support an enormous variety of marine life. The reefs are built by tiny animals that live in partnership with algae. The algae provide food through photosynthesis, while the corals offer shelter and nutrients in return. When water temperatures rise too far, this relationship breaks down, and the corals lose their color in a process called bleaching. Reefs can recover if conditions improve quickly enough.\n\n1. **reefs** (re + *efs*): Repeats \"coral reefs\" from sentence one; plural with \"are\".\n2. **built** (bu + *ilt*): The irregular past participle of \"build\" in the passive \"are built by\".\n3. **tiny** (ti + *ny*): An adjective before \"animals\"; four letters.\n4. **that** (th + *at*): Begins a defining relative clause about the animals.\n5. **in** (i + *n*): The fixed phrase \"in partnership with\".\n6. **with** (wi + *th*): Completes \"in partnership with\".\n7. **The** (T + *he*): The article that begins the next sentence.\n8. **provide** (pro + *vide*): A plural verb without -s, because \"algae\" is plural. Count the blanks: \"pro\" plus four is \"provide\"; \"provides\" would need five.\n9. **through** (thr + *ough*): \"Through\" means \"by means of\" before \"photosynthesis\".\n10. **while** (wh + *ile*): A conjunction that joins two simultaneous contributions. \"Which\" cannot start a clause that has its own subject (\"the corals\")."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:26')::uuid, 'rich_text', 'Drill 7 (Level 2, B2): The power of defaults', 26, '{"markdown":"Topic: behavioral economics.\n\n> People do not always make choices in the way that traditional economic models predict. One wid\\_ \\_ \\_ documented pat\\_ \\_ \\_ \\_ is t\\_ \\_ power o\\_ default opt\\_ \\_ \\_ \\_. When empl\\_ \\_ \\_ \\_ \\_ are automa\\_ \\_ \\_ \\_ \\_ \\_ \\_ enrolled i\\_ workplace sav\\_ \\_ \\_ \\_ plans a\\_ \\_ must actively choose to leave them, participation tends to be higher than when they must actively choose to join. Economists interpret this as evidence that effort and inertia shape decisions alongside careful calculation. Governments have used this insight when designing pension schemes.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:27')::uuid, 'rich_text', 'Drill 7 (Level 2, B2): The power of defaults: answer key and explanations', 27, '{"markdown":"**Full text:** People do not always make choices in the way that traditional economic models predict. One widely documented pattern is the power of default options. When employees are automatically enrolled in workplace savings plans and must actively choose to leave them, participation tends to be higher than when they must actively choose to join. Economists interpret this as evidence that effort and inertia shape decisions alongside careful calculation. Governments have used this insight when designing pension schemes.\n\n1. **widely** (wid + *ely*): An adverb before the participle \"documented\", so it needs -ly.\n2. **pattern** (pat + *tern*): A singular noun after \"documented\" and before \"is\".\n3. **the** (t + *he*): Definite article in \"the power of\".\n4. **of** (o + *f*): Completes \"the power of\".\n5. **options** (opt + *ions*): A plural noun after \"default\"; \"default options\" are choices made for you unless you change them.\n6. **employees** (empl + *oyees*): Plural with \"are\". \"Employers\" has the same length, but people enrolled in workplace savings plans are the staff, so \"employees\".\n7. **automatically** (automa + *tically*): An adverb before \"enrolled\". \"Automatic\" is an -ic adjective, so the adverb is -ally.\n8. **in** (i + *n*): \"Enrolled in\" a plan or course.\n9. **savings** (sav + *ings*): \"Savings plans\" is a fixed compound; the noun keeps its -s.\n10. **and** (a + *nd*): Joins \"are automatically enrolled\" and \"must actively choose\"."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:28')::uuid, 'rich_text', 'Drill 8 (Level 3, C1): How children learn language', 28, '{"markdown":"Topic: theories of first-language acquisition.\n\n> Children acquire their first language with remarkable speed and without formal instruction. Linguists ha\\_ \\_ proposed comp\\_ \\_ \\_ \\_ \\_ explanations f\\_ \\_ this achie\\_ \\_ \\_ \\_ \\_ \\_. Some ar\\_ \\_ \\_ that hum\\_ \\_ \\_ possess a\\_ innate capa\\_ \\_ \\_ \\_ dedicated specif\\_ \\_ \\_ \\_ \\_ \\_ to gra\\_ \\_ \\_ \\_, whereas others maintain that general learning mechanisms, combined with massive exposure to speech, are sufficient. Studies of infants'' sensitivity to statistical patterns in sound sequences have strengthened the second position, though they have not settled the debate. Most researchers now accept that both experience and biology contribute.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:29')::uuid, 'rich_text', 'Drill 8 (Level 3, C1): How children learn language: answer key and explanations', 29, '{"markdown":"**Full text:** Children acquire their first language with remarkable speed and without formal instruction. Linguists have proposed competing explanations for this achievement. Some argue that humans possess an innate capacity dedicated specifically to grammar, whereas others maintain that general learning mechanisms, combined with massive exposure to speech, are sufficient. Studies of infants'' sensitivity to statistical patterns in sound sequences have strengthened the second position, though they have not settled the debate. Most researchers now accept that both experience and biology contribute.\n\n1. **have** (ha + *ve*): Present perfect \"have proposed\" with the plural subject \"Linguists\".\n2. **competing** (comp + *eting*): A participle adjective: \"competing explanations\" are rival explanations. \"Complex\" is too short for the blanks.\n3. **for** (f + *or*): \"An explanation for\" something.\n4. **achievement** (achie + *vement*): A noun after \"this\" that refers back to learning a language quickly; the -ment ending.\n5. **argue** (ar + *gue*): \"Argue that\"; no -s after the plural \"Some\".\n6. **humans** (hum + *ans*): A plural subject for \"possess\".\n7. **an** (a + *n*): The article \"an\" before the vowel sound of \"innate\". \"As\" and \"at\" cannot come before a noun phrase here.\n8. **capacity** (capa + *city*): A noun after the adjective \"innate\"; \"capacity\" means ability.\n9. **specifically** (specif + *ically*): An adverb modifying \"dedicated\"; \"specific\" is an -ic adjective, so -ally.\n10. **grammar** (gra + *mmar*): Spelled with a double \"m\" and \"-ar\", not \"-er\"."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:30')::uuid, 'rich_text', 'Drill 9 (Level 3, C1): Glaciers as sculptors', 30, '{"markdown":"Topic: how ice shapes land.\n\n> Glaciers shape landscapes far more dramatically than their slow movement might suggest. As ea\\_ \\_ glacier adva\\_ \\_ \\_ \\_, it scr\\_ \\_ \\_ \\_ the under\\_ \\_ \\_ \\_ \\_ rock a\\_ \\_ carries aw\\_ \\_ enormous quant\\_ \\_ \\_ \\_ \\_ of sedi\\_ \\_ \\_ \\_. When i\\_ eventually retr\\_ \\_ \\_ \\_, it leaves behind distinctive features, including U-shaped valleys, scattered boulders and long ridges of debris. Geologists use these traces to reconstruct the extent of ancient ice sheets, which in turn helps them estimate how climate fluctuated in the distant past.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:31')::uuid, 'rich_text', 'Drill 9 (Level 3, C1): Glaciers as sculptors: answer key and explanations', 31, '{"markdown":"**Full text:** Glaciers shape landscapes far more dramatically than their slow movement might suggest. As each glacier advances, it scrapes the underlying rock and carries away enormous quantities of sediment. When it eventually retreats, it leaves behind distinctive features, including U-shaped valleys, scattered boulders and long ridges of debris. Geologists use these traces to reconstruct the extent of ancient ice sheets, which in turn helps them estimate how climate fluctuated in the distant past.\n\n1. **each** (ea + *ch*): A determiner before the singular noun \"glacier\".\n2. **advances** (adva + *nces*): A verb with -s after \"each glacier\"; its opposite, \"retreats\", appears later in the paragraph.\n3. **scrapes** (scr + *apes*): A verb with -s describing the physical action on rock.\n4. **underlying** (under + *lying*): An adjective meaning \"lying underneath\", before \"rock\".\n5. **and** (a + *nd*): Joins two actions of \"it\": scrapes… and carries.\n6. **away** (aw + *ay*): The phrasal verb \"carry away\".\n7. **quantities** (quant + *ities*): \"Quantities of\" a substance; \"y\" becomes \"ies\" in the plural.\n8. **sediment** (sedi + *ment*): An uncountable noun after \"of\"; no plural -s.\n9. **it** (i + *t*): The subject pronoun for the glacier.\n10. **retreats** (retr + *eats*): A verb with -s; the opposite of \"advances\"."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:32')::uuid, 'rich_text', 'Drill 10 (Level 3, C1): Who chose the colors?', 32, '{"markdown":"Topic: Renaissance art patronage.\n\n> During the Renaissance, most painters worked on commission rather than producing art for an open market. Patrons, whe\\_ \\_ \\_ \\_ wealthy merc\\_ \\_ \\_ \\_ \\_, religious instit\\_ \\_ \\_ \\_ \\_ \\_ or rul\\_ \\_ \\_ families, typi\\_ \\_ \\_ \\_ \\_ specified t\\_ \\_ subject, t\\_ \\_ dimensions a\\_ \\_ sometimes ev\\_ \\_ the pigm\\_ \\_ \\_ \\_ to be used. Contracts frequently stipulated that expensive blues be applied to particular figures, reflecting the prestige attached to costly materials. Consequently, artistic decisions that modern viewers attribute to individual genius were often negotiated.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:33')::uuid, 'rich_text', 'Drill 10 (Level 3, C1): Who chose the colors?: answer key and explanations', 33, '{"markdown":"**Full text:** During the Renaissance, most painters worked on commission rather than producing art for an open market. Patrons, whether wealthy merchants, religious institutions or ruling families, typically specified the subject, the dimensions and sometimes even the pigments to be used. Contracts frequently stipulated that expensive blues be applied to particular figures, reflecting the prestige attached to costly materials. Consequently, artistic decisions that modern viewers attribute to individual genius were often negotiated.\n\n1. **whether** (whe + *ther*): Introduces a list of alternatives: \"whether X, Y or Z\".\n2. **merchants** (merc + *hants*): A plural person noun after \"wealthy\".\n3. **institutions** (instit + *utions*): A plural -tion noun after \"religious\".\n4. **ruling** (rul + *ing*): A participle adjective: families that ruled.\n5. **typically** (typi + *cally*): An adverb before the verb \"specified\"; the adjective \"typical\" ends in -al, so the adverb is -ally.\n6. **the** (t + *he*): The article in \"the subject\".\n7. **the** (t + *he*): The article in \"the dimensions\".\n8. **and** (a + *nd*): Joins the last item of the list.\n9. **even** (ev + *en*): Signals that something is surprising: they chose even the pigments.\n10. **pigments** (pigm + *ents*): A plural noun: the colored substances used in paint."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:34')::uuid, 'rich_text', 'Drill 11 (Level 4, C1+): A brain that rewires', 34, '{"markdown":"Topic: neural plasticity.\n\n> The adult brain was once thought to be largely fixed in its structure. That assum\\_ \\_ \\_ \\_ \\_ has be\\_ \\_ substantially rev\\_ \\_ \\_ \\_. Experiments wi\\_ \\_ musicians a\\_ \\_ with peo\\_ \\_ \\_ recovering fr\\_ \\_ strokes indi\\_ \\_ \\_ \\_ that neu\\_ \\_ \\_ circuits reorg\\_ \\_ \\_ \\_ \\_ in response to sustained practice or injury. Nevertheless, plasticity is neither unlimited nor uniformly beneficial; maladaptive changes can entrench chronic pain, and the capacity for reorganization appears to diminish, though not disappear, with age. Rehabilitation programs increasingly try to harness this flexibility.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:35')::uuid, 'rich_text', 'Drill 11 (Level 4, C1+): A brain that rewires: answer key and explanations', 35, '{"markdown":"**Full text:** The adult brain was once thought to be largely fixed in its structure. That assumption has been substantially revised. Experiments with musicians and with people recovering from strokes indicate that neural circuits reorganize in response to sustained practice or injury. Nevertheless, plasticity is neither unlimited nor uniformly beneficial; maladaptive changes can entrench chronic pain, and the capacity for reorganization appears to diminish, though not disappear, with age. Rehabilitation programs increasingly try to harness this flexibility.\n\n1. **assumption** (assum + *ption*): A noun after \"That\" referring back to the old belief. The verb is \"assume\", but the noun has a \"p\": \"assumption\".\n2. **been** (be + *en*): Present perfect passive: \"has been revised\".\n3. **revised** (rev + *ised*): A past participle meaning changed or corrected.\n4. **with** (wi + *th*): \"Experiments with\" the people studied.\n5. **and** (a + *nd*): Joins the two groups: musicians and people recovering from strokes.\n6. **people** (peo + *ple*): The noun after \"with\", followed by \"recovering\".\n7. **from** (fr + *om*): \"Recover from\" an illness.\n8. **indicate** (indi + *cate*): A plural verb (the subject is \"Experiments\") followed by \"that\".\n9. **neural** (neu + *ral*): An adjective meaning \"of the nerves\", before \"circuits\".\n10. **reorganize** (reorg + *anize*): A plural present verb without -s (the subject is \"circuits\"); American spelling with -ize."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:36')::uuid, 'rich_text', 'Drill 12 (Level 4, C1+): Trade and inequality', 36, '{"markdown":"Topic: economic theory and evidence.\n\n> Economists have long debated whether trade between nations narrows or widens inequality within them. Classical the\\_ \\_ \\_ predicts th\\_ \\_ opening mar\\_ \\_ \\_ \\_ should ra\\_ \\_ \\_ the wa\\_ \\_ \\_ of wor\\_ \\_ \\_ \\_ whose ski\\_ \\_ \\_ are relat\\_ \\_ \\_ \\_ \\_ abundant, wh\\_ \\_ \\_ depressing t\\_ \\_ earnings of those in scarce supply. Empirical findings, however, have proven considerably messier, partly because technological change and trade liberalization frequently occurred simultaneously, making their respective contributions exceedingly difficult to disentangle. The question remains central to debates about globalization.\n\n**Your task:** write the 10 completed words in order before you open the answer key below."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:37')::uuid, 'rich_text', 'Drill 12 (Level 4, C1+): Trade and inequality: answer key and explanations', 37, '{"markdown":"**Full text:** Economists have long debated whether trade between nations narrows or widens inequality within them. Classical theory predicts that opening markets should raise the wages of workers whose skills are relatively abundant, while depressing the earnings of those in scarce supply. Empirical findings, however, have proven considerably messier, partly because technological change and trade liberalization frequently occurred simultaneously, making their respective contributions exceedingly difficult to disentangle. The question remains central to debates about globalization.\n\n1. **theory** (the + *ory*): A singular subject for \"predicts\". \"These\" would need a plural noun.\n2. **that** (th + *at*): \"Predicts that + clause\".\n3. **markets** (mar + *kets*): \"Opening markets\" means removing barriers to trade.\n4. **raise** (ra + *ise*): The transitive verb \"raise\" takes an object (\"the wages\"). \"Rise\" cannot take an object.\n5. **wages** (wa + *ges*): \"The wages of workers\" is the pay they earn.\n6. **workers** (wor + *kers*): A person noun, signalled by \"whose\".\n7. **skills** (ski + *lls*): A plural noun with \"are\".\n8. **relatively** (relat + *ively*): An adverb before the adjective \"abundant\".\n9. **while** (wh + *ile*): \"While + -ing\" sets up a contrast with the first effect.\n10. **the** (t + *he*): The article in \"the earnings of\"."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:38')::uuid, 'rich_text', 'Scoring yourself and logging misses', 38, '{"markdown":"After each drill, write the score out of 10 and the time. Then log **every miss** with one of these labels:\n\n- **SLOT:** wrong part of speech (adjective where a noun was needed)\n- **FAMILY:** right word family, wrong ending\n- **AGREE:** wrong -s, tense or plural\n- **PHRASE:** did not recognise the collocation or fixed phrase\n- **SMALL:** wrong short word (*it/is, as/an, that/this*)\n- **SPELL:** right word, wrong spelling\n- **VOCAB:** did not know the word\n\nAfter all twelve drills, count the labels. If **SLOT** and **FAMILY** dominate, return to Clues 1 and 2 and make your own drills from academic texts. If **VOCAB** dominates, you need more reading at the level of the drills you failed, with new words recorded in families and with their partners. Copy the counts into your main error log, described in the [Band 4 to 5 Roadmap](/guide-band-4-to-5-roadmap)."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:39')::uuid, 'rich_text', 'Build your own drills', 39, '{"markdown":"Once you have used all twelve, make more from any academic text:\n\n1. Choose a paragraph of 70–100 words from a textbook, encyclopaedia or quality news article.\n2. Leave the first sentence complete.\n3. Starting with the second word of the second sentence, take every second word until you have ten.\n4. Keep the first half of each chosen word (rounded down) and replace the rest with one blank per letter.\n5. Solve it the next day, so you do not remember the text.\n\nMaking drills is itself a useful exercise: choosing the gaps makes you notice word forms. Pair up with a study partner and swap drills for a fair test."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:40')::uuid, 'callout', 'Never leave a gap empty', 40, '{"label":"A blank cannot earn the point","body":"Each scored Complete the Words item is worth up to one point, and ETS describes no penalty for a wrong answer. If time is short, write your best candidate for every gap from the visible letters and the slot. A reasoned guess often turns out right; an empty gap never does."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:41')::uuid, 'faq', 'Frequently asked questions', 41, '{"items":[{"question":"Are the drills in this guide real TOEFL texts?","answer":"No. All twelve paragraphs were written for Schood in the format ETS describes: about 70–100 words, an intact first sentence, every second word half-removed, ten gaps. They are practice material, not official ETS items."},{"question":"Does capitalisation or spelling matter in my answer?","answer":"Treat spelling as essential: the task is about form as well as meaning, and the missing letters must make the correct word. Use the spelling the text uses, which in ETS materials is American."},{"question":"What if two words fit the same gap?","answer":"Use all the clues together. The blank count fixes the length, the slot fixes the part of speech, and agreement fixes the ending. In well-made items only one word satisfies all three and the meaning."},{"question":"How many paragraphs will I see on test day?","answer":"The blueprint lists 30 target Complete the Words items, and ETS''s description says each paragraph has 10 gaps. Because Reading is adaptive, the exact set you see depends on your performance."},{"question":"How fast should I be?","answer":"ETS does not publish a time per paragraph. Measure your own baseline, then aim to get faster without falling below 9 out of 10. Accuracy is worth more than speed in this task."}]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-complete-the-words-drills:42')::uuid, 'cta_strip', 'Your next step', 42, '{"label":"Put the routine under test conditions","primary_text":"Practise Reading in the simulator","primary_url":"https://toefl.schood.online/practice","secondary_text":"Back to the Complete the Words module","secondary_url":"/reading-complete-the-words","surface":"premium"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb)
) as v(id, block_type, heading, sort_order, content, metadata)
join public.toefl_playbook_pages p on p.locale_code = 'en' and p.slug = 'guide-complete-the-words-drills'
on conflict do nothing;

