insert into public.toefl_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, p.id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (values
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:1')::uuid, 'rich_text', 'Why structures, not scripts', 1, '{"markdown":"The public modules [Write an Email](/writing-email) and [Write for an Academic Discussion](/writing-academic-discussion) explain what each task asks. This guide gives you **structures you can adapt in seconds** and the language that moves a response from a 4 to a 5 on ETS''s 0–5 scoring guides.\n\nA structure is not a memorised script. ETS''s scoring guides reward elaboration that supports the communicative purpose, appropriate social conventions, syntactic variety and precise word choice. A pasted script does the opposite: it ignores the reader, repeats the same sentences as thousands of other candidates and usually misses one of the required points. The lowest score descriptions even mention responses that mostly borrow language from the prompt.\n\nWhat you will learn instead is a **flexible frame**: a fixed order of moves, and a bank of ways to perform each move, so that every response is new but you never have to plan from nothing."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:2')::uuid, 'checklist', 'What you will be able to do', 2, '{"items":["Plan and write a complete email in 7 minutes, covering every bullet in the prompt","Choose the right register for a professor, an office, a manager or a classmate","Write a discussion post that takes a clear position and adds something new","Use hedging, qualifying and concession language naturally","Follow a timing plan that leaves two minutes to proofread","Recognise the mistakes that hold a response at 3 or 4"]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:3')::uuid, 'rich_text', 'The two tasks in numbers', 3, '{"markdown":"From **ETS''s overview and blueprint**:\n\n| | Write an Email | Write for an Academic Discussion |\n|---|---|---|\n| Time | 7 minutes | 10 minutes |\n| Prompt | A scenario plus usually three things to do | A professor''s question plus two student posts |\n| Purpose | A specific communicative goal: request, recommend, invite, propose a solution | State and support an opinion, contribute to the discussion |\n| Score | 0–5 | 0–5 |\n| Length guidance | \"Write as much as you can and in complete sentences\" | \"An effective response will contain at least 100 words\" |\n\nBoth tasks are AI scored and sit in the Writing section with ten Build a Sentence items. The blueprint gives the section 20 raw points: 10 from Build a Sentence and 5 from each of these two tasks."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:4')::uuid, 'rich_text', 'What a 5 looks like on the scoring guides', 4, '{"markdown":"ETS''s guides describe a **5 email** as effective and clearly expressed, with elaboration that effectively supports the purpose, effective syntactic variety, precise and idiomatic word choice, consistent appropriate social conventions (politeness, register, organisation, how requests or refusals are phrased) and almost no errors beyond typical timed slips.\n\nA **5 discussion post** is a relevant and very clearly expressed contribution, with relevant, well-elaborated explanations, examples or details, a variety of structures, precise and idiomatic word choice and almost no errors.\n\nThe **4** in both guides is \"generally successful\": adequate elaboration, some variety, appropriate (not precise) word choice, few errors. ETS''s own sample email was held at 4 by a single kind of consequential error in verb form.\n\nSo the move from 4 to 5 has three parts: **elaborate with purpose, choose precise words, and remove errors.** Everything in this guide serves one of those three."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:5')::uuid, 'rich_text', 'The email frame', 5, '{"markdown":"Use these five moves, in this order:\n\n1. **Greeting and context (1 sentence).** Who you are, or why you are writing, in relation to the reader.\n2. **Bullet one, developed (2–3 sentences).** State it, then add one detail or reason.\n3. **Bullet two, developed (2–3 sentences).** The same pattern.\n4. **Bullet three, developed (2–3 sentences).** Often the request or the proposal; make the action clear.\n5. **Close (1–2 sentences).** A polite next step and a sign-off appropriate to the reader.\n\nTwo rules matter more than anything else:\n\n- **Every bullet gets its own developed paragraph or sentence group.** Missing or thinly treating a bullet is the fastest way to lose the \"achieves the communicative goal\" part of the score.\n- **The reader decides the register.** The frame stays the same; the language changes with who will read it."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:6')::uuid, 'rich_text', 'Register: one request, three readers', 6, '{"markdown":"The same request, adjusted for three readers. Notice how the moves stay, while the tone and the phrasing change.\n\n**To a professor (formal, respectful):**\n> Dear Professor Okafor, I am writing to ask whether it would be possible to submit my lab report two days after the deadline. I would be grateful for any flexibility you can offer.\n\n**To a campus office (polite, efficient):**\n> Dear Housing Office team, I would like to request a later move-in date for my room. Could you let me know whether this is possible and what I need to do?\n\n**To a classmate (friendly, direct):**\n> Hi Sam, could you send me your notes from Tuesday''s lecture? I had to leave early and I missed the last part.\n\nRegister checklist:\n\n- **Formal:** full forms (*I would*), modal requests (*Would it be possible…*), titles (*Professor*, *Dr.*), thanks without exaggeration.\n- **Polite and efficient:** clear requests (*Could you let me know…*), no slang, short paragraphs.\n- **Friendly:** contractions, direct questions, a warm close. Still complete sentences and correct grammar."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:7')::uuid, 'rich_text', 'The functions bank', 7, '{"markdown":"Most email bullets ask you to perform one of a small set of functions. Have **two ways** to do each:\n\n| Function | Neutral to formal | Friendly |\n|---|---|---|\n| Request | Would it be possible to…? / I would be grateful if you could… | Could you…? / Any chance you could…? |\n| Apologise | I apologise for… and I will make sure that… | Sorry about… I''ll… |\n| Explain a problem | Unfortunately, when I tried to…, the system… | The thing is, when I tried to… |\n| Recommend | I would recommend… because… | You should definitely… it''s… |\n| Invite | I would like to invite you to… which will take place on… | Do you want to come to…? |\n| Propose a solution | One option might be to…, which would… | What if we…? That way… |\n| Decline politely | I am afraid I will not be able to…; however, I could… | I can''t make it, but how about…? |\n| Thank | Thank you for taking the time to… | Thanks so much for… |\n\nUse the frame to place each function, then develop it with one concrete detail: a date, a reason, a consequence."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:8')::uuid, 'rich_text', 'Model email 1: missed registration (formal)', 8, '{"markdown":"**Prompt (original, for practice):** Your environmental science course is organising a visit to a water treatment plant. Registration closed while you were away for a family event, and you did not see the reminder. Write to your professor, Dr. Lindqvist. In your email: explain why you did not register; ask whether a place is still available; suggest what you could do if the visit is full.\n\n> **Subject:** Water treatment plant visit\n>\n> Dear Dr. Lindqvist,\n>\n> I am a student in your Tuesday environmental science section, and I am writing about the visit to the water treatment plant. I was away last week for my sister''s wedding, and I only saw the registration reminder after the form had closed. I should have checked the course page before I left, and I am sorry for the inconvenience.\n>\n> I would be grateful if you could tell me whether a place is still available. The visit is directly related to the filtration unit we are studying, so I would very much like to see the process in person.\n>\n> If the group is already full, I would be happy to join a waiting list in case someone cancels. Alternatively, I could complete an extra reading assignment on the plant''s treatment stages so that I do not miss the content.\n>\n> Thank you for considering my request.\n>\n> Kind regards,\n> Aziz Karimov\n\n**Annotation:**\n\n- **All three bullets are covered**, each in its own paragraph: why (paragraph 1), availability (paragraph 2), alternatives (paragraph 3).\n- **Elaboration supports the purpose:** the reason for wanting a place (\"directly related to the filtration unit\") makes the request stronger, not just longer.\n- **Social conventions:** a brief, sincere apology that accepts responsibility; a modal request (*I would be grateful if…*); two concrete alternatives instead of pressure.\n- **Precise words:** *filtration unit*, *treatment stages*, *in case someone cancels*.\n- **Variety:** a relative clause, a conditional (*If the group is already full…*), a purpose clause (*so that I do not miss…*)."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:9')::uuid, 'rich_text', 'Model email 2: recommending a course (friendly)', 9, '{"markdown":"**Prompt (original):** Your friend Leila is choosing between two summer courses you have both heard about: Public Speaking and Introduction to Data Analysis. You took one of them last year. Write to Leila. In your email: say which course you recommend; explain why; give her one piece of advice for doing well.\n\n> **Subject:** Summer course advice\n>\n> Hi Leila,\n>\n> Great to hear you''re planning a summer course! If I were you, I''d go for Introduction to Data Analysis, the one I took last year.\n>\n> The main reason is that it''s surprisingly practical. Instead of just learning formulas, we spent most classes working with real data sets, like bus timetables and weather records, and by the end I could build simple charts that I''ve since used in two other courses. Public Speaking is useful too, but you already present well, so I think the data course would teach you more.\n>\n> My one piece of advice: don''t skip the first two weeks of spreadsheet exercises, even if they seem easy. Everything later builds on them, and the people who fell behind early found it hard to catch up.\n>\n> Let me know what you decide, and good luck!\n>\n> Best,\n> Dilnoza\n\n**Annotation:**\n\n- **Register fits a friend:** contractions, an exclamation, *If I were you, I''d…*, a warm close. Still fully grammatical.\n- **The recommendation is justified by a specific, personal detail** (bus timetables, charts used in two other courses), which is what \"elaboration that effectively supports the communicative purpose\" looks like.\n- **A comparison with the other option** shows the recommendation is reasoned, not random.\n- **The advice is concrete and explained** (why the first two weeks matter)."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:10')::uuid, 'rich_text', 'Model email 3: proposing a solution (polite, efficient)', 10, '{"markdown":"**Prompt (original):** The library''s new online system for booking group study rooms has been double-booking rooms. Last week your group arrived to find another group in the room you had reserved. Write to the library services manager. In your email: describe the problem; explain how it affected your group; propose a solution.\n\n> **Subject:** Double bookings in the study room system\n>\n> Dear Library Services Manager,\n>\n> I am writing to report a problem with the new group study room booking system. Last Thursday my group reserved Room 4 from 3 to 5 p.m. and received a confirmation email, but when we arrived another group was already there with a confirmation for the same time.\n>\n> Because every other room was occupied, we had to hold our project meeting in the café, where it was too noisy to rehearse our presentation. It was the last meeting we had planned before the deadline, so the timing was particularly unfortunate.\n>\n> One possible solution would be to show each room''s bookings on a screen at the door, so that groups could spot a conflict before a session starts. In the meantime, it might help if staff at the front desk could check a printed list when two groups claim the same room.\n>\n> Thank you for looking into this. I would be happy to share my confirmation email if it would help.\n>\n> Yours sincerely,\n> Javohir Tursunov\n\n**Annotation:**\n\n- **Facts first, then impact, then solution**, matching the bullets in order.\n- **Specific details** (Room 4, 3 to 5 p.m., the confirmation email) make the problem credible and clear.\n- **The solution is constructive and hedged** (*One possible solution would be…*, *it might help if…*): firm content, polite form.\n- **An offer of help at the end** is a small social convention that strong emails often include."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:11')::uuid, 'rich_text', 'The discussion frame', 11, '{"markdown":"Your post joins a conversation, so it must do two things: **take a position** and **add something the other posts did not say.** Use these moves:\n\n1. **Position (1–2 sentences).** Answer the professor''s question directly. You may respond to one classmate by name.\n2. **Main reason (2–3 sentences).** One reason, explained, not three reasons listed.\n3. **Specific support (2–3 sentences).** An example, a consequence or a brief scenario: something concrete.\n4. **Engage the other side (1–2 sentences).** Acknowledge the strongest opposing point and answer it, or refine your position.\n5. **Close (1 sentence).** A sentence that states the takeaway, not a summary of everything.\n\n**What counts as \"new\":** a different reason, a specific example, a practical consequence, a condition under which your view changes, or a reply to a classmate''s point. Restating what Priya or Tomás said in different words is not a contribution."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:12')::uuid, 'rich_text', 'Model discussion 1: cars in historic centres', 12, '{"markdown":"**Prompt (original):** *Professor Ramos:* Many cities with historic centres are debating whether to ban private cars from those areas. Supporters say it protects old buildings and makes streets safer; critics say it hurts local businesses and makes access harder. Should cities ban private cars from their historic centres? Why or why not?\n\n*Priya:* Yes. Car pollution damages old stone buildings, and narrow streets were never designed for traffic. A ban protects the heritage that attracts visitors in the first place.\n\n*Tomás:* I disagree. Shops in these areas depend on customers who drive in, and older residents may struggle without a car. A ban could empty the centre instead of saving it.\n\n> I agree with Priya that a ban makes sense, but Tomás''s concern about access is the real test of whether it works. In my view, the policy succeeds only when the space taken from cars is given to something better than cars. When my city closed its old market street to traffic, the first year was difficult, exactly as Tomás predicts: two shops near the entrance closed. However, the council then added a frequent electric shuttle from the car parks and allowed delivery vans in the early morning. Within a couple of years, the street had more people on it than before, because walking there became pleasant rather than merely possible. So I would support a ban, but only as part of a package that includes reliable public transport and exemptions for residents with limited mobility. Banning cars without replacing what they provided would simply move the problem somewhere else.\n\n**Annotation:**\n\n- **Position plus engagement in the first sentence:** it names both classmates and sets up a refined view.\n- **The contribution is new:** neither classmate mentioned the conditions that make a ban work (shuttle, deliveries, exemptions).\n- **The example is specific and personal**, and it concedes the opposing point honestly (shops closed) before answering it.\n- **Precise language:** *pleasant rather than merely possible*, *as part of a package*, *limited mobility*.\n- **About 150 words**, comfortably above ETS''s guidance of at least 100 words, written in 10 minutes with time to check."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:13')::uuid, 'rich_text', 'Model discussion 2: recorded lectures', 13, '{"markdown":"**Prompt (original):** *Dr. Haddad:* Some universities now record every lecture and post the videos online for students. Should universities record all lectures? Why or why not?\n\n*Mei:* Yes. Recordings let students review difficult material and help anyone who is ill or has to work.\n\n*Daniel:* No. If every lecture is online, fewer students will attend, and the live discussion that makes lectures valuable will disappear.\n\n> Daniel is right that attendance might fall, but I think that tells us something about lectures rather than about recordings. If a session is nothing more than a speaker reading slides, students lose very little by watching it later at double speed. Recording would therefore push lecturers to make the live session worth attending, for example by using part of the time for questions, short problems or debates that a video cannot reproduce. Mei''s point about reviewing material is also stronger than it first appears: in my statistics course, I rewatched one explanation of sampling error three times before it finally made sense, which would have been impossible from my notes alone. For these reasons, I believe universities should record lectures, as long as they also redesign the in-person part of the course so that attending still offers something extra.\n\n**Annotation:**\n\n- **Reframes the debate** (attendance falling as a signal about lecture quality), which is a genuine contribution.\n- **Uses one classmate''s point to strengthen the position** and supports it with a precise personal example.\n- **Logical connectors** (*therefore*, *for example*, *for these reasons*, *as long as*) make the argument easy to follow without sounding mechanical."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:14')::uuid, 'rich_text', 'Band 5–6 language that sounds natural', 14, '{"markdown":"Use these sparingly: one or two per paragraph, where they make the meaning more exact.\n\n- **Hedging certainty:** *is likely to*, *tends to*, *in most cases*, *it seems reasonable to assume that*.\n- **Limiting a claim:** *at least in the short term*, *as long as*, *provided that*, *except where*.\n- **Conceding then answering:** *Admittedly, … ; even so, …* / *While it is true that …, this overlooks …*\n- **Precise contrast:** *whereas*, *by contrast*, *rather than*, *not so much X as Y*.\n- **Emphasis by structure:** *What concerns me most is…*, *It is not the cost but the time that…*\n- **Consequences:** *which means that*, *as a result*, *this would in turn*.\n\nETS''s C1 descriptor for writing mentions precisely qualifying opinions by degree of certainty and expressing disagreement diplomatically. These phrases are how you do both in a short response."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:15')::uuid, 'rich_text', 'Timing plans', 15, '{"markdown":"**Write an Email (7 minutes):**\n\n| Minute | Action |\n|---|---|\n| 0–1 | Read the scenario and bullets; note the reader and one detail for each bullet |\n| 1–5:30 | Write greeting, three developed bullets and close |\n| 5:30–7 | Proofread: verbs, articles, agreement, spelling; check every bullet is covered |\n\n**Write for an Academic Discussion (10 minutes):**\n\n| Minute | Action |\n|---|---|\n| 0–1.5 | Read the professor and both students; choose a position and your new point |\n| 1.5–8 | Write position, reason, specific support, engagement and close |\n| 8–10 | Proofread and sharpen one vague word per paragraph |\n\nPractise both timings in the [simulator](https://toefl.schood.online/practice) until the proofread happens automatically."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:16')::uuid, 'rich_text', 'The two-minute proofread', 16, '{"markdown":"In this order, because this order catches the errors that cost the most:\n\n1. **Verb forms and tense:** *can be sent*, not *can sent*; *I have taken*, not *I have took*.\n2. **Subject–verb agreement:** *the system doesn''t*, *students who live*.\n3. **Articles:** *a deadline*, *the course page*, no article with general plurals.\n4. **Plural -s and word forms:** *two poems*, *successfully*, *responsible*.\n5. **Spelling of key words:** especially the words copied from the prompt.\n6. **Bullet check (email) or contribution check (discussion):** is every required point there?\n\nWrite your own top five recurring errors on a card and check those first. Your personal list beats any general list."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:17')::uuid, 'rich_text', 'Mistakes that hold scores at 3 or 4', 17, '{"markdown":"- **Missing a bullet**, or mentioning it in a few words at the end.\n- **The wrong register:** *Hey prof* to a professor, or stiff formality to a friend.\n- **Generic elaboration:** \"This is very important for everyone\" instead of a concrete detail.\n- **Repeating a classmate** in the discussion instead of adding to the conversation.\n- **Listing three reasons** with one sentence each, instead of developing one reason well.\n- **Memorised openings** that do not fit the prompt (\"In today''s modern world…\").\n- **Skipping the proofread** because the response \"feels finished\".\n- **Copying long phrases from the prompt**: ETS''s low-score descriptors mention language mostly borrowed from the stimulus."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:18')::uuid, 'rich_text', 'Practice prompts', 18, '{"markdown":"Write each one under time, then compare with the frame and the annotations above. All prompts are original.\n\n**Emails (7 minutes):**\n\n1. Your student club wants to invite a local engineer to speak. Write to her: introduce the club, explain why you chose her, and suggest two possible dates.\n2. You bought a used textbook from the campus shop but it is the wrong edition. Write to the shop: describe the problem, explain why the edition matters, and ask what they can do.\n3. A classmate missed the group meeting where tasks were divided. Write to him: summarise the decisions, tell him his task, and ask him to confirm.\n\n**Discussions (10 minutes):**\n\n1. Should first-year university students be required to live on campus?\n2. Should museums be free for everyone, even if this means less funding for exhibitions?\n3. Is it better for students to specialise early or to study a broad range of subjects first?"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:19')::uuid, 'rich_text', 'Feedback loop', 19, '{"markdown":"For each practice response, record in your error log:\n\n- **Task score** if you used the simulator''s feedback, or your own score against the ETS descriptors.\n- **Bullets covered** (email) or **new contribution made** (discussion): yes or no.\n- **Errors found in proofread** and **errors found later** (the second number is what the proofread missed).\n- **One upgraded word or sentence** you would change now.\n\nReview the log weekly. If \"errors found later\" stays high, your proofread is too fast or in the wrong order. The [Band 4 to 5 Roadmap](/guide-band-4-to-5-roadmap) shows how to fold this into a full weekly plan."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:20')::uuid, 'callout', 'Templates are a starting point', 20, '{"label":"Make the frame invisible","body":"The best responses use a clear structure that the reader never notices. If a sentence could be pasted into any response on any topic, replace it with one that only makes sense for this prompt. Specific beats impressive."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:21')::uuid, 'faq', 'Frequently asked questions', 21, '{"items":[{"question":"How long should my email be?","answer":"ETS asks you to write as much as you can in complete sentences, and the scoring guide rewards elaboration that supports the purpose. As a starting point, aim for about 100–150 words that you can finish and proofread in seven minutes, then adjust after timing yourself. The model emails in this guide run to about 140–170 words; treat them as something to work toward, not a minimum."},{"question":"Is 100 words enough for the discussion?","answer":"ETS''s prompt states that an effective response will contain at least 100 words. Treat 100 as a floor. A developed post with one reason, one specific example and one engagement point usually runs longer."},{"question":"Can I invent an example from \"my experience\"?","answer":"The task asks you to support your opinion with your own reasoning, experiences or knowledge. A plausible, specific scenario is a normal way to support a point; what matters for the score is relevance, clarity and language quality."},{"question":"Should I name the classmates in my post?","answer":"It is a natural way to engage with the discussion and makes your contribution clearly connected. It is not required; what is required is that you add something of your own."},{"question":"British or American spelling?","answer":"Either is correct English. Be consistent within a response. ETS''s own materials use American spelling."}]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-email-and-discussion-templates:22')::uuid, 'cta_strip', 'Your next step', 22, '{"label":"Write one email and one discussion post today","primary_text":"Practise Writing in the simulator","primary_url":"https://toefl.schood.online/practice","secondary_text":"Review the Academic Discussion module","secondary_url":"/writing-academic-discussion","surface":"premium"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb)
) as v(id, block_type, heading, sort_order, content, metadata)
join public.toefl_playbook_pages p on p.locale_code = 'en' and p.slug = 'guide-email-and-discussion-templates'
on conflict do nothing;

-- guide-final-14-days: 29 sections
insert into public.toefl_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, p.id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (values
  (md5('schood-toefl-pb-section:guide-final-14-days:1')::uuid, 'rich_text', 'How to use the last two weeks', 1, '{"markdown":"The final two weeks are not the time to learn new skills. They are the time to **make your existing skills reliable under test conditions**, remove the errors you already know about, and make sure nothing outside the test (ID, equipment, deadlines, sleep) costs you points.\n\nThis plan counts down from **Day 14** (two weeks before the test) to **Day 1** (the day before), followed by **test day**. It includes:\n\n- **two full mocks** in the [Schood TOEFL simulator](https://toefl.schood.online/full-exam), one on Day 14 and one on Day 7\n- a **review protocol** for each mock\n- **targeted repair days** driven by your error log\n- the **ETS deadlines** that fall inside these two weeks\n- **test-day routines** for a test center and for the Home Edition\n\nPlan about 1.5 to 2.5 hours a day on most days, less in the final three days. If your schedule is tighter, keep the two mock days and the two review days, and shorten the others."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:2')::uuid, 'checklist', 'What you will be able to do', 2, '{"items":["Run two full mocks under realistic conditions and review them properly","Turn mock results into a short list of final priorities","Meet every ETS deadline: rescheduling, ID, score recipients","Prepare a Home Edition room and computer that pass check-in","Follow a calm, practised routine on test day","Decide in advance whether to report or cancel your scores"]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:3')::uuid, 'rich_text', 'Ground rules for the final fortnight', 3, '{"markdown":"1. **No new materials.** Use the simulator, the drills you already know and your error log. New books and new methods create doubt.\n2. **Test conditions on mock days.** Same time of day as your test, same desk, same note-taking material, and no pauses between sections: ETS states there are no scheduled breaks in the TOEFL iBT.\n3. **Sleep is preparation.** Keep a consistent bedtime for the whole fortnight, especially the last five days.\n4. **The error log decides.** After each mock, your two largest error categories become the priorities. Your mood does not.\n5. **Protect the strong sections.** Spend short daily sessions on them so they do not slip while you repair the weak ones."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:4')::uuid, 'rich_text', 'Before Day 14: the admin check', 4, '{"markdown":"Do these now, because some cannot be fixed later:\n\n- **Name match:** the name in your ETS account must exactly match the name on your ID, as the 2026–27 Bulletin requires. Check every letter.\n- **ID:** a valid, original, physical, government-issued ID with your photo and signature; expired or digital IDs are not accepted. Check the ID rules for your testing location on the ETS website.\n- **Home Edition only:** download the TOEFL Test App from the My TOEFL Home dashboard and run the equipment check. If identity verification through a mobile app applies to you, the Bulletin asks you to complete it at least 48 hours before the test.\n- **Accommodations:** these must be approved before you register, so if you need them and do not have them, contact ETS now and consider your date.\n- **Score recipients:** your fee includes up to four score reports to institutions you choose. List them now so you are not deciding at the last minute."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:5')::uuid, 'timeline', 'The fortnight at a glance', 5, '{"items":[{"label":"Day 14","value":"Full mock 1 under test conditions"},{"label":"Day 13","value":"Review mock 1; choose two priorities"},{"label":"Day 12","value":"Priority 1 repair; Complete the Words set"},{"label":"Day 11","value":"Priority 2 repair; timed email and discussion"},{"label":"Day 10","value":"Speaking accuracy and interview frameworks; academic listening"},{"label":"Day 9","value":"Section mock of the weakest section, then review"},{"label":"Day 8","value":"Mixed light practice; logistics rehearsal"},{"label":"Day 7","value":"Full mock 2 under test conditions"},{"label":"Day 6","value":"Review mock 2; reschedule decision; confirm recipients"},{"label":"Day 5","value":"Repair the two largest categories from mock 2"},{"label":"Day 4","value":"Timed writing pair and speaking set"},{"label":"Day 3","value":"Short mixed sets; review your top-ten error list"},{"label":"Day 2","value":"Logistics day; light practice only"},{"label":"Day 1","value":"Rest, short warm-up, pack, sleep early"}]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:6')::uuid, 'rich_text', 'Day 14: full mock 1', 6, '{"markdown":"Take a **full exam in the [simulator](https://toefl.schood.online/full-exam)** at the same time of day as your test. Follow the real order: Reading, Listening, Writing, Speaking.\n\nConditions:\n\n- One sitting, no pauses between sections, phone in another room.\n- **Test center candidates:** use pencil and paper for notes.\n- **Home Edition candidates:** use only your whiteboard or a sheet in a transparent sheet protector with an erasable marker, and use speakers rather than headphones, because ETS does not allow headsets or earphones at home.\n\nAfter the mock, do only a **15-minute first look**: write your section bands, how each section felt for time, and the one thing that surprised you. The deep review is tomorrow, when you are rested."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:7')::uuid, 'rich_text', 'Day 13: review mock 1', 7, '{"markdown":"Run the full **review protocol** (described later in this guide) on mock 1. It takes about 90 minutes.\n\nAt the end, write on one card:\n\n- your **section bands** and the overall average, rounded the ETS way (to the nearest half band)\n- your **two priority categories** for the next week, from the error-log counts\n- one **maintenance task** for each strong section\n\nIf you are near a target line, check which section offers the cheapest next half band. The [Band 4 to 5](/guide-band-4-to-5-roadmap) and [Band 5 to 6](/guide-band-5-to-6-roadmap) roadmaps explain the averaging arithmetic."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:8')::uuid, 'rich_text', 'Day 12: priority 1 repair', 8, '{"markdown":"Spend about 75 minutes on priority 1 with drills that target the exact category, not the whole section:\n\n- **Reading form or vocabulary errors:** two or three paragraphs from the [Complete the Words Drills](/guide-complete-the-words-drills), timed, with every miss logged.\n- **Reading purpose or inference errors:** academic passages with a one-line purpose note per paragraph before answering.\n- **Listening detail or reply errors:** short sets of Choose a Response and announcements, labelling reply types.\n- **Writing accuracy:** one email with a full two-minute proofread, then a second proofread a day later to see what you missed.\n- **Speaking exactness:** ten Listen and Repeat sentences, recorded and checked word by word.\n\nAdd 20 minutes of maintenance for one strong section."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:9')::uuid, 'rich_text', 'Day 11: priority 2 repair and writing', 9, '{"markdown":"Repeat yesterday''s approach for priority 2 (about 60 minutes), then write **one email in 7 minutes and one discussion post in 10 minutes** under time.\n\nCompare both with the frames in [Email and Discussion Templates](/guide-email-and-discussion-templates):\n\n- Did the email cover every bullet, in the right register?\n- Did the discussion post add something new rather than repeat a classmate?\n- How many errors did the proofread catch, and how many did you find afterwards?\n\nLog the results. If the second number is high, your proofread order needs fixing."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:10')::uuid, 'rich_text', 'Day 10: speaking and academic listening', 10, '{"markdown":"Speaking comes last in the test, when you are most tired, so it gets its own day:\n\n- **Listen and Repeat (20 minutes):** long sentences, one repetition each, recorded and checked.\n- **Interview (30 minutes):** two full four-question interviews using the frameworks in [Interview Answer Frameworks](/guide-interview-answer-frameworks). Record them and score one against the self-scoring checklist.\n- **Academic listening (30 minutes):** three academic talks, noting purpose and structure while listening, then answering."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:11')::uuid, 'rich_text', 'Day 9: section mock of the weakest section', 11, '{"markdown":"Take a **timed section** of your weakest section in the [simulator practice area](https://toefl.schood.online/practice), then review it with the same protocol as a full mock.\n\nCompare the result with the same section in mock 1. Do not over-read one result: a section mock taken fresh is often slightly better than the same section at the end of a two-hour test. What you are looking for is whether the **priority categories are shrinking**."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:12')::uuid, 'rich_text', 'Day 8: light practice and logistics rehearsal', 12, '{"markdown":"A lighter day, with one important job:\n\n- **Home Edition:** run the equipment check again **on the same weekday and at the same time of day as your test**, as ETS recommends, because bandwidth varies. Set up the room exactly as on test day (details later) and sit a 20-minute practice set in it.\n- **Test center:** confirm the address, plan the route and the travel time, and decide when you must leave home to arrive **at least 30 minutes early**, which the Bulletin requires.\n\nThen do 45 minutes of mixed light practice: one Complete the Words paragraph, two announcements, one email."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:13')::uuid, 'rich_text', 'Day 7: full mock 2', 13, '{"markdown":"Full exam in the [simulator](https://toefl.schood.online/full-exam), under the same conditions as Day 14: same time of day, same notes material, no pauses.\n\nIf you are taking the Home Edition, take this mock **in your test room, on your test computer**. If you are going to a test center, take it somewhere unfamiliar if you can, such as a library study room, to practise concentrating in a new space.\n\nAgain, only a 15-minute first look today."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:14')::uuid, 'rich_text', 'Day 6: review mock 2 and make decisions', 14, '{"markdown":"Run the review protocol on mock 2, then compare both mocks side by side:\n\n| | Mock 1 | Mock 2 |\n|---|---|---|\n| Reading band | | |\n| Listening band | | |\n| Writing band | | |\n| Speaking band | | |\n| Overall (rounded) | | |\n| Two largest error categories | | |\n\nThen make two decisions:\n\n- **Keep the date or reschedule.** ETS requires rescheduling or cancelling at least **four full days** before the test (for a Saturday test, by Tuesday), and cancelling by that deadline refunds 50% of the fee. Make this decision today, calmly, using both mocks.\n- **Confirm score recipients.** The Bulletin allows you to add, delete or change your free score recipients until **10 p.m. local test center time on the day before the test**. Settle the list today and do not leave it for Day 1."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:15')::uuid, 'rich_text', 'Day 5: repair from mock 2', 15, '{"markdown":"Use mock 2''s two largest categories. If they are the same as after mock 1, the drills you used last week are not targeting the real error. Change the drill, not just the amount:\n\n- Reading misses still on purpose questions? Switch from answering questions to writing paragraph functions first.\n- Writing errors still in verbs? Make a personal list of your five recurring verb errors and check only those in a fast proofread.\n- Speaking answers still short? Use the shrinking-timer routine with a 45-second final recording.\n\nAbout 90 minutes in total, plus 20 minutes of maintenance."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:16')::uuid, 'rich_text', 'Day 4: final timed writing and speaking', 16, '{"markdown":"A short, sharp session (about 75 minutes):\n\n- One **email** (7 minutes) and one **discussion** (10 minutes), each with the proofread.\n- One full **interview** (four questions) and seven **Listen and Repeat** sentences.\n\nReview quickly, log the results and stop. From now on the goal is confidence and rhythm, not volume."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:17')::uuid, 'rich_text', 'Day 3: short mixed sets and your top-ten list', 17, '{"markdown":"- **45 minutes of mixed practice:** one Complete the Words paragraph, one Daily Life set, one academic passage, one conversation and one academic talk.\n- **20 minutes:** write your **top-ten error list** from the log: the ten mistakes you are most likely to make, each with its fix in one line (\"*a/an before vowel sounds*\", \"*check -s after he/she/it*\", \"*no replay in my head: answer and move on*\").\n\nRead the list once more in the evening. It will be the last thing you study."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:18')::uuid, 'rich_text', 'Day 2: logistics day', 18, '{"markdown":"Light practice only (30 minutes at most). The rest of the day is preparation:\n\n- **ID** in your bag or on your desk, checked against your ETS account name.\n- **Test center:** confirm your appointment details and route; plan to eat before you leave, because there are no scheduled breaks, and prepare any medication you need.\n- **Home Edition:** clear the desk and the room; check the camera can be moved for a full room view including the desk surface and the area below it; prepare your whiteboard and marker or your sheet protector; charge the phone or mirror you will use at check-in; close and disable screen-sharing and remote-access software."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:19')::uuid, 'rich_text', 'Day 1: the day before', 19, '{"markdown":"- **20-minute warm-up:** one Complete the Words paragraph, two Listen and Repeat sentences, a 45-second answer to one interview question. Nothing timed, nothing new.\n- **Read your top-ten list once.**\n- **Final recipients check** before 10 p.m. local test center time, if you did not finish it on Day 6.\n- **Pack or set up** everything tonight.\n- **Sleep at your usual time.** A late-night review does more harm than good."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:20')::uuid, 'rich_text', 'Mock conditions that match the real test', 20, '{"markdown":"To make your two mocks useful, recreate what ETS describes:\n\n- **Section order:** Reading, Listening, Writing, Speaking.\n- **Timing:** ETS lists approximate base times of 30 minutes for Reading, 29 for Listening, 23 for Writing and 8 for Speaking, and advises allowing about two hours in total including directions. Times can vary because Reading and Listening adapt.\n- **No scheduled breaks.**\n- **Notes:** paper and pencil provided at a test center; only an erasable whiteboard or a sheet in a protector at home.\n- **Audio once:** never replay listening audio in a mock.\n\nA mock that breaks these conditions gives you a band that is not comparable to test day."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:21')::uuid, 'rich_text', 'The review protocol', 21, '{"markdown":"Use this for both full mocks and for section mocks. Budget about 90 minutes for a full mock.\n\n1. **Copy results (5 minutes).** Section bands, timing notes and how each section felt.\n2. **Reading and Listening misses (30 minutes).** For each miss: the task type, your answer, the correct answer, and one sentence explaining what you should have noticed. Label it with a category.\n3. **Writing (20 minutes).** Reread both responses. Mark every error, then check: all bullets covered, new contribution made, register right.\n4. **Speaking (20 minutes).** Listen to your recordings if available. Mark Listen and Repeat changes, and judge each interview answer for directness, elaboration and pace.\n5. **Count and choose (10 minutes).** Count entries per category. The two largest are your priorities. Write tomorrow''s tasks.\n6. **One evidence sentence (5 minutes).** Write what changed since the last mock, using only numbers you measured.\n\nUse the [simulator''s review pages](https://toefl.schood.online/review) to go back through each item. Remember that Schood mock bands are practice estimates that follow the ETS format and descriptors; your official scores come only from ETS."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:22')::uuid, 'rich_text', 'Test-day routine at a test center', 22, '{"markdown":"**Morning:**\n- Eat a normal breakfast at your usual time. Do not try new food or extra caffeine.\n- A five-minute warm-up: read a short English paragraph aloud and answer one interview question in your head.\n\n**Arrival and check-in (from the 2026–27 Bulletin):**\n- Arrive **at least 30 minutes before** your start time. If you arrive or check in after the start time, you cannot test and the fee is not refunded.\n- Bring your **valid ID**. Expect identity checks such as photographs, signature comparison and other verification, and security checks of clothing and pockets.\n- **Personal items** go into the storage the staff show you; phones must be switched off and cannot be accessed during the session. The Bulletin limits food and drink in the testing room, so eat beforehand and follow the administrator''s instructions on where food, drinks and medication are kept.\n- Remove face masks, large jewellery and hair accessories before entering; wedding and engagement rings can stay on.\n\n**In the room:**\n- The administrator provides **pencils and scratch paper**. Do not write on anything else, and do not use the paper before the test or between sections. Return all of it at the end.\n- There are **no scheduled breaks**, so start the test ready to work for about two hours."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:23')::uuid, 'rich_text', 'Test-day routine for the Home Edition', 23, '{"markdown":"**The room (from ETS''s Home Edition requirements):**\n- You must be **alone in a closed room**, not in a public place. Cover transparent walls, doors or large open windows, and clear the walls of test-related material.\n- Desk or table surface with the computer and keyboard on it, **connected to power**. Sit in a standard chair, not on a bed or sofa. The door should be visible to the proctor.\n- The desk and the area around it must be clear of everything not approved: notes, books, phones, cameras.\n\n**The equipment:**\n- A desktop or laptop (no tablets), **one monitor, one keyboard**, a licensed operating system (ETS currently lists Windows 11 or higher, or Mac OS X 10.13 or higher; check the equipment check for the latest).\n- An internal or external **speaker and microphone; headsets and earphones are not allowed**.\n- A camera that can be moved to show the proctor a full view of the room, including the desk surface and the area below it.\n- Screen-sharing and remote-access software closed and disabled.\n\n**Check-in (from the Bulletin):**\n- You can start check-in **up to 15 minutes before** your scheduled time and **no later than 30 minutes after** it; after that the test is cancelled without a refund.\n- Have a **phone or hand-held mirror** for check-in; afterwards the phone goes behind you and out of reach, unless it is your approved second camera.\n- Notes only on **one small whiteboard with an erasable marker**, or **one blank sheet inside a transparent sheet protector** with an erasable marker; the sheet must never leave the protector. At the end you will show the proctor that your notes are erased.\n- **No food or drink** during the test, no unscheduled breaks, and stay in view of the proctor. Ears and face must stay visible."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:24')::uuid, 'rich_text', 'During the test: section reminders', 24, '{"markdown":"- **Reading:** take the first items carefully; the first stage decides the difficulty of the second. Answer every Complete the Words gap, even with a best guess.\n- **Listening:** one play only. Track purpose and structure for talks; label reply types for short exchanges.\n- **Writing:** Build a Sentence quickly but carefully, then 7 minutes for the email and 10 for the discussion, each ending with your proofread.\n- **Speaking:** in Listen and Repeat, hear the whole sentence, then repeat it in meaning groups. In the interview, answer directly in your first sentence and close at around 40 seconds.\n- **If something goes wrong:** at a test center, raise your hand and tell the administrator; at home, follow the proctor''s instructions. Do not stop working on your own unless you are told to."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:25')::uuid, 'rich_text', 'After the test', 25, '{"markdown":"What ETS''s policies say happens next:\n\n- At the end of the test you see **unofficial Reading and Listening scores** and the date your official scores are expected. They can occasionally change after ETS''s quality checks.\n- You then choose to **report or cancel** your scores. Cancelling covers all sections, cannot be undone at that moment and gives no refund; cancelled scores can be **reinstated within 60 days** for a fee. Reported scores cannot be cancelled later.\n- **Official scores** are posted to your ETS account about **3 days** after the test, and the PDF score report is ready about a day after that.\n- Scores are **valid for 2 years**. Your report also shows **MyBest scores**, the highest section scores from valid tests in the last two years.\n- You can request a **score review of Speaking and/or Writing** within 30 days of the test, for a fee, but not after scores have been sent to any institution. Reading and Listening cannot be reviewed.\n- If you need another attempt, you can test again, but **not more than once in any three-day period**. The [Retake and MyBest Strategy](/retake-and-mybest-strategy) module helps you decide."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:26')::uuid, 'rich_text', 'Report or cancel? Decide now', 26, '{"markdown":"Make this decision before test day, when you are calm, and write it on your card:\n\n- **Report** unless something went clearly and badly wrong (illness, a serious technical problem, a section you could not complete).\n- Remember that you will only see **Reading and Listening** unofficial scores when you decide. A lower-than-hoped Reading score is not, on its own, a good reason to cancel: your Writing and Speaking may be stronger than you feel, and MyBest scores can later combine your best sections if your institutions accept them.\n- If you set up free score reports to institutions, reporting sends them your scores. If you would rather see the scores before an institution does, decide whether to list recipients in advance or order reports later for a fee."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:27')::uuid, 'callout', 'Panic protocol', 27, '{"label":"If a section goes badly, the next one starts at zero","body":"Each section is scored separately and then averaged. A difficult Reading section does not lower your Listening, Writing or Speaking scores unless you carry the frustration into them. Between sections, take one slow breath, read your first instruction carefully and treat the next section as a new test."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:28')::uuid, 'faq', 'Frequently asked questions', 28, '{"items":[{"question":"Should I take a full mock the day before the test?","answer":"No. A full mock on Day 1 tires you and can shake your confidence for no gain. The plan''s last full mock is on Day 7, with lighter practice afterwards."},{"question":"What if my mock 2 result is lower than mock 1?","answer":"Look at the error categories, not just the band. One lower mock is normal variation. If both mocks are below your target and the gap is large, use Day 6 to decide whether to keep the date; ETS requires at least four full days'' notice to reschedule."},{"question":"Can I eat or drink during the Home Edition?","answer":"No. ETS''s Home Edition requirements state that food and drink are not allowed during the test, and there are no scheduled breaks."},{"question":"Can I use headphones for the Home Edition?","answer":"No. ETS requires an internal or external speaker and a microphone that is not part of a headset. Practise your listening mocks through speakers too."},{"question":"When can I send scores to more institutions?","answer":"Up to four free score reports are included if you choose recipients before the deadline. After that, you can order additional score reports through your ETS account for a fee."}]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-final-14-days:29')::uuid, 'cta_strip', 'Your next step', 29, '{"label":"Book Day 14 in your calendar","primary_text":"Start full mock 1","primary_url":"https://toefl.schood.online/full-exam","secondary_text":"Read the public test-day guide","secondary_url":"/test-day-guide","surface":"premium"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb)
) as v(id, block_type, heading, sort_order, content, metadata)
join public.toefl_playbook_pages p on p.locale_code = 'en' and p.slug = 'guide-final-14-days'
on conflict do nothing;

-- guide-interview-answer-frameworks: 33 sections
insert into public.toefl_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, p.id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (values
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:1')::uuid, 'rich_text', 'What this guide adds', 1, '{"markdown":"The public [Take an Interview](/speaking-take-an-interview) module explains the task. This guide is the training system. It gives you:\n\n- a **framework for each of the four interview questions**, built for a 45-second answer\n- **fluency and prosody routines** you can run in 15 minutes a day\n- an **accuracy routine for Listen and Repeat**, which carries most of the section''s raw points\n- **twelve original model answers**: each of the four questions answered at a band 4, band 5 and band 6 level, with commentary\n\nThe goal is not to sound rehearsed. ETS''s scoring guide rewards answers that are on topic and well elaborated, delivered at a good conversational pace, intelligible, with rhythm and intonation that carry meaning, and with accurate, varied language. A framework gives you the structure so that your attention can go to the language."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:2')::uuid, 'checklist', 'What you will be able to do', 2, '{"items":["Recognise which of the four question types you are hearing within the first seconds","Start speaking quickly with a direct answer, then build a 45-second response","Elaborate with one reason and one specific example instead of a list of general points","Control pace, pauses, stress and intonation","Repeat long sentences exactly in Listen and Repeat","Judge your own recordings against the ETS descriptors for scores 3, 4 and 5"]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:3')::uuid, 'rich_text', 'The Speaking section in numbers', 3, '{"markdown":"From ETS''s blueprint and overview:\n\n- **Listen and Repeat:** 7 sentences in a campus or academic scenario. The sentences get longer and more complex. You have a maximum of **8 to 12 seconds** to record each repetition, and you repeat **only once**.\n- **Take an Interview:** a simulated conversation with a pre-recorded interviewer, in a situation such as a scholarship application or a research study. **4 questions, 45 seconds** to answer each.\n- **Scoring:** all **11 items are scored 0–5**, so the section has **55 raw points**. Listen and Repeat accounts for 35 of them and the interview for 20.\n- **Timing:** about **8 minutes** for the whole section, which comes last in the test.\n\nAccording to ETS, the earlier interview questions focus on factual information and personal experience, and later questions ask you to express and support opinions on broader issues. The blueprint adds that prompts move from brief factual statements toward opinion, explanation, prediction and narration, with difficulty increasing across the task."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:4')::uuid, 'rich_text', 'The four question types', 4, '{"markdown":"Schood uses four labels for the four interview questions. They follow the progression ETS describes; the exact wording on test day will vary.\n\n| Question | Type | What it asks |\n|---|---|---|\n| 1 | **Recall** | Describe a specific past experience: what happened, why, what you liked |\n| 2 | **Reaction** | How you usually feel or act in a situation, and why |\n| 3 | **Position** | Do you agree with a general claim about people or society? |\n| 4 | **Proposal** | Should an institution (a university, a city, a government) do something? |\n\nThe first two are about **you**; the last two are about **the world**. Recognising the type in the first two seconds tells you which framework to use."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:5')::uuid, 'rich_text', 'The 45-second shape', 5, '{"markdown":"Every framework below follows the same timing shape:\n\n| Seconds | Move |\n|---|---|\n| 0–5 | Direct answer in one sentence |\n| 5–20 | Main reason or main detail, explained |\n| 20–38 | One specific example, story or consequence |\n| 38–45 | Closing line that links back to the question |\n\nThree rules:\n\n- **Start within about two seconds.** Long silences at the start are expensive. Your first sentence can simply restate the question as an answer.\n- **One reason, developed,** is better than three reasons listed. The 4 and 5 descriptors are about elaboration, not number of points.\n- **Finish your sentence when time ends.** If the timer stops you mid-sentence, nothing terrible happens, but a closing line at around 38–40 seconds makes the answer feel complete."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:6')::uuid, 'rich_text', 'Framework 1: Recall', 6, '{"markdown":"**Structure:** *When and where → what happened → one vivid detail → why it mattered to you.*\n\nUseful openings:\n- *The last time I… was in [month], when I…*\n- *One experience that comes to mind is…*\n\nUseful development:\n- *What I remember most is…*\n- *The reason I decided to… was that…*\n- *It mattered to me because…*\n\n**Common trap:** describing a general habit (\"I usually travel in summer\") when the question asks for one specific occasion. Choose one event and stay with it."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:7')::uuid, 'rich_text', 'Framework 2: Reaction', 7, '{"markdown":"**Structure:** *My usual reaction → the cause → a moment that shows it → a nuance or exception.*\n\nUseful openings:\n- *I''d say I''m definitely someone who…*\n- *Honestly, my first reaction is usually…*\n\nUseful development:\n- *I think that''s because…*\n- *For example, last month…*\n- *That said, it depends on…*\n\n**Common trap:** stating the reaction and stopping. The question almost always has a *why* part; the cause is where your elaboration lives."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:8')::uuid, 'rich_text', 'Framework 3: Position', 8, '{"markdown":"**Structure:** *Verdict → main reason → example or evidence → brief concession → restate.*\n\nUseful openings:\n- *I mostly agree with that, because…*\n- *I don''t think that''s true for everyone. In my view…*\n\nUseful development:\n- *The main reason is…*\n- *You can see this in…*\n- *Of course, some people… but even so…*\n\n**Common trap:** answering \"it depends\" without ever choosing. You can qualify your view, but give one clearly."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:9')::uuid, 'rich_text', 'Framework 4: Proposal', 9, '{"markdown":"**Structure:** *Yes or no → the benefit or harm → how it would work in practice → a condition or cost.*\n\nUseful openings:\n- *Yes, I think universities should do that, mainly because…*\n- *I''m not convinced that''s a good idea, because…*\n\nUseful development:\n- *In practice, that would mean…*\n- *For example, they could…*\n- *The only condition I''d add is…*\n\n**Common trap:** talking only about values (\"it is good for society\") without a mechanism. Say how the proposal would actually work or fail."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:10')::uuid, 'rich_text', 'The model interview', 10, '{"markdown":"The twelve model answers below respond to one original interview, written for Schood in the style ETS describes.\n\n**Scenario:** *You have agreed to take part in a university research study about how students spend their free time. A researcher will interview you online.*\n\n1. **Recall:** \"Tell me about a time recently when you learned a new skill outside of your classes. What was it, and why did you decide to learn it?\"\n2. **Reaction:** \"Some people like to plan their free time carefully, while others prefer to decide at the last minute. Which kind of person are you, and why?\"\n3. **Position:** \"Some people say that hobbies are more valuable when you do them with other people rather than alone. Do you agree? Why or why not?\"\n4. **Proposal:** \"Some universities give students academic credit for activities outside the classroom, such as volunteering or team sports. Should universities do this? Why or why not?\"\n\n**How to read the levels:** the labels band 4, band 5 and band 6 are Schood''s editorial illustrations of performance consistent with the ETS descriptors for B2, C1 and C2 speaking. They are not ETS-rated samples. Transcripts include natural fillers; ETS''s own score-5 samples contain *um* and *uh* too."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:11')::uuid, 'rich_text', 'Question 1 at band 4', 11, '{"markdown":"> Um, recently I learned how to cook some, uh, dishes from my country. I learned it from videos on the internet. I decided to learn because I live in dormitory now and I miss my mother food. So I watched videos and I tried to cook plov, it''s rice with meat. First time it was not very good, but second time it was better. I think cooking is useful skill because you can save money and also it''s healthy. So, yes, I''m happy I learned it.\n\n**Commentary:** The answer is on topic and has a clear sequence, which is what the scoring guide''s 3–4 range rewards. Pausing is noticeable but does not block meaning. What holds it at this level: small but frequent grammar slips (*in dormitory*, *my mother food*, *useful skill*), simple sentence patterns joined with *and* and *so*, and a general final reason. To move up: fix articles and possessives, and replace the general ending with a specific detail."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:12')::uuid, 'rich_text', 'Question 1 at band 5', 12, '{"markdown":"> The most recent one was learning to cook plov, which is a rice dish from Uzbekistan. I moved into a dormitory in September, and after a few weeks of cafeteria food I really started to miss home cooking. So I called my mother, and she talked me through it on a video call while I cooked. The first attempt was, um, a bit of a disaster, because I added the rice too early and it turned into porridge. But by the third try my roommates were actually asking for seconds. What I liked most was that it gave me a reason to call home every weekend, so it turned into more than just a cooking skill.\n\n**Commentary:** Well elaborated and clearly organised: when, why, how, one vivid detail (the rice turning into porridge), and why it mattered. Grammar and vocabulary are accurate and varied (a relative clause, *talked me through it*, *asking for seconds*). The one filler is natural. This is the profile of a 5 on the task guide: on topic, well elaborated, good pace, clear meaning."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:13')::uuid, 'rich_text', 'Question 1 at band 6', 13, '{"markdown":"> Just last month, actually, I taught myself to repair my own bicycle. It started out of pure frustration: my gears kept slipping on the hill up to campus, and the only repair shop nearby had a two-week waiting list. So I found a mechanic''s channel online, borrowed a set of tools from a neighbour, and spent a Saturday afternoon taking the derailleur apart on my balcony. What surprised me was how logical it all was once I understood that the problem was just one cable that had stretched. Now I do small repairs for a couple of friends, and, more importantly, I''ve lost that slightly helpless feeling I used to have whenever something mechanical broke.\n\n**Commentary:** Fluent and precise from the first word. The answer narrates with control (*It started out of pure frustration*), uses less common vocabulary accurately (*derailleur*, *stretched*), and ends with a reflective point that is specific rather than general (*that slightly helpless feeling*). This matches the C2 description of clear, smoothly flowing and memorable descriptions."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:14')::uuid, 'rich_text', 'Question 2 at band 4', 14, '{"markdown":"> I think I am a person who plans. Because I am student, I have many classes and homework, so I need to plan. If I don''t plan, I forget things. For example, on weekend I write what I will do on Saturday and Sunday, like study, sport, and meet friends. But sometimes my friends call me and say, let''s go somewhere now, and I go, so I am not always planning. I think planning is better for students.\n\n**Commentary:** Answers the question and gives a reason and an example, so the content is relevant. It stays at this level because the sentences are short and similar, articles are missing (*I am student*, *on weekend*), and the nuance at the end is mentioned but not developed. To move up: join ideas with a wider range of connectors and develop the exception into a real point."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:15')::uuid, 'rich_text', 'Question 2 at band 5', 15, '{"markdown":"> I''d say I''m mostly a planner, but not in a strict way. During the week my schedule is so full with classes and my part-time job that if I don''t plan my free time, it simply disappears. So on Sunday evenings I block out two or three things I actually want to do, like going to the climbing gym on Wednesday. Having it on the calendar makes me protect that time. That said, I leave Saturdays completely open on purpose, because some of the best evenings I''ve had were last-minute plans with friends. So I''d call myself a planner with one free day.\n\n**Commentary:** Clear position, a convincing cause (a full schedule), a specific habit (Sunday planning, the climbing gym) and a developed nuance (the open Saturday). Connectors (*so*, *that said*, *because*) carry the logic. A typical 5: elaborated, coherent, accurate."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:16')::uuid, 'rich_text', 'Question 2 at band 6', 16, '{"markdown":"> I''m a planner by necessity rather than by temperament. Left to myself, I''d happily drift through a weekend, but I''ve noticed that unplanned free time tends to get swallowed by small obligations: laundry, emails, a quick errand that takes two hours. So I schedule my free time almost as seriously as my classes. On Thursday nights, for instance, I book a tennis court for Saturday morning, and once it''s paid for, I go. The irony is that planning is what makes me feel spontaneous, because the things I actually care about are already protected, and everything else can be decided on the day.\n\n**Commentary:** The opening contrast (*by necessity rather than by temperament*) is precise and immediately sets up a nuanced answer. Vocabulary is idiomatic and exact (*drift*, *swallowed by small obligations*), and the closing irony is a genuinely interesting idea expressed with ease. This is the C2 profile: precise formulation, no sign of restricting what the speaker wants to say."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:17')::uuid, 'rich_text', 'Question 3 at band 4', 17, '{"markdown":"> Yes, I agree. When you do hobby with other people, it is more fun. For example, I play football with my friends every week. We talk, we laugh, and we become closer. If I play alone, it is boring. Also with other people you can learn from them. But some hobbies, like reading, you do alone, and it is also good. So I think both is OK, but with people is better.\n\n**Commentary:** A clear position and an example, which keeps it on topic. It stays here because of agreement errors (*both is*), missing articles and a closing line that wavers between positions. Rhythm is choppy because almost every sentence is the same length. To move up: develop one reason fully and keep one clear position."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:18')::uuid, 'rich_text', 'Question 3 at band 5', 18, '{"markdown":"> I partly agree. For hobbies that involve skill, like music or sport, doing them with others definitely adds value, because other people push you further than you''d go alone. When I started playing in a small band at my school, I improved faster in three months than I had in a year of practising by myself, simply because I didn''t want to let the others down. But I don''t think it''s true for every hobby. Something like drawing or reading is valuable precisely because it''s solitary; it''s one of the few times I''m not responding to anyone. So it depends on what the hobby is for.\n\n**Commentary:** A qualified position stated clearly, a reason with a mechanism (*push you further*, *let the others down*), a specific example and a well-developed contrast. The ending gives a reasoned principle rather than a vague *it depends*. Strong control of grammar and vocabulary: a typical 5."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:19')::uuid, 'rich_text', 'Question 3 at band 6', 19, '{"markdown":"> I''d push back on that a little, because it assumes the value of a hobby is social, and often it isn''t. Some hobbies are clearly richer in company: it''s hard to imagine choir singing or five-a-side football on your own. But for many people, a hobby is the one part of the day where nobody is evaluating them. My grandfather builds model ships, alone, for hours, and he''d tell you the solitude is the whole point; it''s the only time his mind is completely quiet. So I''d say the question isn''t whether a hobby is shared, but whether it gives you something your working life doesn''t.\n\n**Commentary:** The speaker challenges the assumption behind the claim, which is a sophisticated move delivered naturally. The example is concrete and memorable, and the final reframing is precise. Grammar and vocabulary are wide-ranging and controlled throughout, with natural rhythm implied by the contrast structures."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:20')::uuid, 'rich_text', 'Question 4 at band 4', 20, '{"markdown":"> I think yes, universities should give credit. Volunteering and sport are good for students. They learn teamwork and responsibility. Also, some students don''t have time for these activities because they study a lot, so if they get credit, they will do it more. For example, my friend volunteers in a hospital and she learned many things. So I think it is good idea.\n\n**Commentary:** A clear answer with a reason and an example. It stays in the middle range because the elaboration is general (*learned many things*), there is no explanation of how credit would work, and some grammar slips remain (*it is good idea*). To move up: add a practical mechanism and one specific detail about the friend''s experience."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:21')::uuid, 'rich_text', 'Question 4 at band 5', 21, '{"markdown":"> Yes, I think they should, as long as the credit is connected to something students actually learn. Activities like volunteering or team sports teach skills that classes don''t, such as handling responsibility or working with people you didn''t choose. If universities gave, say, one course credit for a semester of regular volunteering, more students would be able to fit it into their schedules instead of treating it as an extra. To keep it fair, though, students should have to write a short reflection or have a supervisor confirm their hours. Otherwise, it would just become an easy way to collect credits.\n\n**Commentary:** Answer, benefit, mechanism and condition: the full proposal framework, delivered clearly. The conditional (*If universities gave…, more students would…*) and the concession (*To keep it fair, though…*) show range. A typical 5."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:22')::uuid, 'rich_text', 'Question 4 at band 6', 22, '{"markdown":"> I''d support it, but only if the credit rewards reflection rather than attendance. The case for it is strong: some of the most useful things students learn, like managing a team or dealing with someone in distress, happen outside lectures, and right now students who can''t afford to give up paid work are effectively excluded from them. Credit would change that calculation. The risk is that it turns volunteering into box-ticking, where people log hours without engaging. So I''d tie the credit to a short piece of work afterwards, explaining what they learned and what they''d do differently. That keeps the academic value without making it bureaucratic.\n\n**Commentary:** The answer adds a perspective that is easy to miss (students who must work are excluded), names a risk precisely (*box-ticking*), and proposes a concrete safeguard. Vocabulary is exact (*change that calculation*, *bureaucratic*) and the argument flows without visible effort, consistent with the C2 descriptor."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:23')::uuid, 'rich_text', 'What separates the three levels', 23, '{"markdown":"| Feature | Band 4 | Band 5 | Band 6 |\n|---|---|---|---|\n| Elaboration | A reason and a general example | A reason with a mechanism and a specific example | A reframed or nuanced point, precise and memorable |\n| Grammar | Simple patterns, frequent small slips | Varied structures, accurate | Wide range, controlled, flexible |\n| Vocabulary | Common words, some wrong forms | Appropriate and some idiomatic | Precise and idiomatic, with connotation |\n| Delivery | Noticeable pauses, choppy rhythm | Good pace, natural pauses | Smooth flow, pauses only to choose words |\n\nUse this table to judge your own recordings. **Change one row at a time.**"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:24')::uuid, 'rich_text', 'Routine 1: thought groups', 24, '{"markdown":"Natural English is spoken in **thought groups**: short chunks of meaning separated by tiny pauses, each with one main stressed word.\n\n> *When I moved into the dormitory* / *I really started to miss* / *home cooking.*\n\nPractice:\n\n1. Take a model answer from this guide.\n2. Mark thought groups with slashes and underline one stressed word in each.\n3. Read it aloud three times, pausing only at the slashes.\n4. Record the third reading and listen: are the pauses at the slashes, or in the middle of phrases?\n\nPauses inside a thought group sound like searching; pauses between thought groups sound like thinking. The scoring guide''s \"appropriate and natural use of pauses\" is exactly this difference."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:25')::uuid, 'rich_text', 'Routine 2: stress and intonation', 25, '{"markdown":"Rhythm and intonation that convey meaning are named in the score-5 description. Practise three patterns:\n\n- **Contrast stress:** \"It''s not the *money*, it''s the *time*.\" Stress the two contrasting words.\n- **New information stress:** in \"I learned to cook *plov*\", the new word carries the stress.\n- **Falling intonation for statements and conclusions,** and a slight rise on items in a list before the last one: \"I need *time*↗, *money*↗ and a *plan*↘.\"\n\nPractise with short sentences until the stress is automatic, then read a model answer and exaggerate the patterns. Exaggeration in practice becomes natural emphasis in the test."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:26')::uuid, 'rich_text', 'Routine 3: shadowing', 26, '{"markdown":"Shadowing means speaking along with a recording, a fraction of a second behind it.\n\n1. Choose 30–60 seconds of clear natural speech: a lecture, a podcast or an interview.\n2. Listen once without speaking.\n3. Shadow it three times, copying the rhythm and intonation, not just the words.\n4. Record your last attempt and compare.\n\nRotate North American, British and Australian speakers, because the test''s audio uses all three. Ten minutes of shadowing a day trains both fluency and the listening speed that Listen and Repeat needs."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:27')::uuid, 'rich_text', 'Routine 4: the shrinking timer', 27, '{"markdown":"This routine trains fluency by repeating the same answer under less time:\n\n1. Answer a practice question in **60 seconds**.\n2. Answer the same question again in **45 seconds**, keeping all the content.\n3. Answer it a third time in **35 seconds**.\n4. Answer it once more at **45 seconds** and record it.\n\nThe final 45-second version is usually more fluent and better organised than the first, because the structure and words have become automatic. Use a new question every day."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:28')::uuid, 'rich_text', 'Routine 5: Listen and Repeat accuracy', 28, '{"markdown":"Listen and Repeat is worth more raw points than the interview, and its scoring guide is strict: a 5 is an exact, fully intelligible repetition; a 4 has minor changes such as a missing function word or tense marker; a 3 keeps most content words but changes meaning.\n\nDaily routine (10 minutes):\n\n1. Collect sentences of increasing length from campus or academic contexts: directions, rules, schedules, announcements.\n2. Play each sentence once, wait one second, repeat it once, record.\n3. Compare word by word with the script. Mark every changed or missing word.\n4. Count **function words** (*the, a, to, of, have*) and **endings** (*-ed, -s, -ing*) separately; these are what move a 5 to a 4.\n5. Repeat the hardest five sentences the next day.\n\nHear long sentences as thought groups, not as strings of words: *\"For students with a parking permit / the lot behind the gym / is open until ten.\"* The [Listen and Repeat](/speaking-listen-and-repeat) module covers the task in detail."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:29')::uuid, 'rich_text', 'Recovery language', 29, '{"markdown":"Mistakes happen in every recording. What matters is that you keep going smoothly:\n\n- **Self-correction:** *I went there in June, sorry, in July…* Keep it short and continue.\n- **Buying a second:** *That''s a good question.* / *Let me think about that for a moment.* Use once, not in every answer.\n- **Finding a word:** *It''s a kind of… a tool you use for…* Paraphrase rather than stopping.\n- **Restarting a sentence:** *What I mean is…*\n\nETS''s score-5 descriptor allows natural pauses; its score-3 descriptor mentions frequent or lengthy pauses and frequent fillers. The difference is frequency and length, not whether a filler ever appears."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:30')::uuid, 'rich_text', 'Recording and self-scoring', 30, '{"markdown":"Record every practice answer. Once a day, score one recording against this checklist:\n\n- **On topic:** did I answer the actual question in my first sentence?\n- **Elaboration:** one reason with a mechanism, and one specific example?\n- **Pace:** did I keep talking until about 40 seconds without long gaps?\n- **Intelligibility:** were any words hard to understand when I listened back?\n- **Language:** how many grammar slips did I hear? Which ones repeat?\n\nWrite the answers in your error log using the speaking categories from the [Band 4 to 5 Roadmap](/guide-band-4-to-5-roadmap): S-exact, S-flow and S-develop. Use the [simulator](https://toefl.schood.online/practice) for timed sets with the real interface."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:31')::uuid, 'callout', 'The memorised-answer trap', 31, '{"label":"Prepare frameworks, not paragraphs","body":"A memorised answer that does not match the question is worse than an imperfect real answer: it is off topic, its rhythm sounds recited, and its language often comes from someone else. Prepare your frameworks, your connectors and a few true personal stories that can be adapted, and build each answer fresh."}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:32')::uuid, 'faq', 'Frequently asked questions', 32, '{"items":[{"question":"Do I lose points for saying \"um\"?","answer":"ETS''s own score-5 sample answers contain fillers such as \"um\" and \"uh\", and the scoring comment says they are natural and do not interfere with meaning. Frequent or lengthy pauses and fillers are mentioned at the score-3 level. Aim to reduce them, not to eliminate them."},{"question":"What if I cannot think of a real experience?","answer":"A plausible, specific example is better than a general statement. Keep a short list of true stories (a course you liked, a trip, a skill you learned, a problem you solved) that can answer many Recall and Reaction questions."},{"question":"How fast should I speak?","answer":"Speak at a good conversational pace that you can control. Speed itself is not the goal; ETS describes a good conversational pace with natural pauses. Fast speech with errors and unclear words scores lower than steady, clear speech."},{"question":"Should I use advanced vocabulary?","answer":"Use words you can pronounce clearly and use correctly. Precise, natural words help; difficult words used wrongly hurt intelligibility and accuracy."},{"question":"What happens if the 45 seconds end in the middle of my sentence?","answer":"The recording stops. Plan your closing line for around 38–40 seconds so that the answer ends naturally."}]}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-section:guide-interview-answer-frameworks:33')::uuid, 'cta_strip', 'Your next step', 33, '{"label":"Record your four answers today","primary_text":"Practise Speaking in the simulator","primary_url":"https://toefl.schood.online/practice","secondary_text":"Back to the Take an Interview module","secondary_url":"/speaking-take-an-interview","surface":"premium"}'::jsonb, '{"seeded_by":"20261028100910_toefl_playbook_premium_guides","content_revision":"toefl-2026-premium-v1"}'::jsonb)
) as v(id, block_type, heading, sort_order, content, metadata)
join public.toefl_playbook_pages p on p.locale_code = 'en' and p.slug = 'guide-interview-answer-frameworks'
on conflict do nothing;

